import {FormControl, Heading, Label, Radio, RadioGroup, type SelectPanelItemInput} from '@primer/react'
import type {Product} from '../../types/products'
import styles from './BudgetProductSelector.module.css'
import {use, useState} from 'react'
import type {PricingDetails} from '../../types/pricings'
import {SelectPanelWrapper} from './BudgetSelectPanelWrapper'
import type {Products} from '../../constants'
import {PRODUCT_TAB_ICON_MAP, PRODUCT_TAB_TEXT_MAP} from '../../constants'
import {MarkGithubIcon} from '@primer/octicons-react'
import {InlineMessage} from '@primer/react/experimental'
import {ModelsBillingErrorMessage} from './ModelsBillingErrorMessage'
import {PageContext} from '../../App'
import {BudgetCopilotPolicyLink} from './BudgetCopilotPolicyLink'

interface Props {
  products: Product[]
  skus: PricingDetails[]
  budgetType: string
  budgetValue: string
  setBudgetType: React.Dispatch<React.SetStateAction<string>>
  setBudgetValue: React.Dispatch<React.SetStateAction<string>>
  isUserRoute: boolean
  showSkuError: boolean
  showModelsBillingError?: boolean
  skuFilter: string
  setSkuFilter: React.Dispatch<React.SetStateAction<string>>
}

export function BudgetProductSelector({
  products,
  skus,
  budgetType,
  budgetValue,
  setBudgetType,
  setBudgetValue,
  showSkuError,
  showModelsBillingError,
  skuFilter,
  setSkuFilter,
}: Props) {
  const {isOrganizationRoute, isUserRoute} = use(PageContext)

  // Map product name to number of SKUs
  const productSkuCounts: Record<string, number> = skus.reduce(
    (acc, sku) => {
      acc[sku.product] = (acc[sku.product] || 0) + 1
      return acc
    },
    {} as Record<string, number>,
  )

  const emptyItem = {id: '', text: ''}

  const productItems: SelectPanelItemInput[] = products
    .filter(product => skus.some(sku => sku.product === product.name)) // Filter out products with no corresponding SKUs
    .map(product => ({
      text: PRODUCT_TAB_TEXT_MAP[product.name as Products],
      leadingVisual: (() => {
        const Icon = PRODUCT_TAB_ICON_MAP[product.name as Products] || MarkGithubIcon
        return <Icon size={16} />
      }) as React.FC,
      id: product.name,
    }))
    .sort((a, b) => a.text.localeCompare(b.text))

  const skuPricingProductItems: SelectPanelItemInput[] = products
    .filter(product => (productSkuCounts[product.name] ?? 0) > 1)
    .map(product => ({
      text: PRODUCT_TAB_TEXT_MAP[product.name as Products],
      leadingVisual: (() => {
        const Icon = PRODUCT_TAB_ICON_MAP[product.name as Products] || MarkGithubIcon
        return <Icon size={16} />
      }) as React.FC,
      id: product.name,
    }))
    .sort((a, b) => a.text.localeCompare(b.text))

  const skuItems: SelectPanelItemInput[] = skus
    .filter(sku => (productSkuCounts[sku.product] ?? 0) > 1)
    .map(sku => ({
      text: sku.friendlyName,
      id: sku.friendlyName,
      descriptionVariant: 'block' as const,
    }))
    .sort((a, b) => a.text.localeCompare(b.text))

  const [selectedProduct, setSelectedProduct] = useState<SelectPanelItemInput>(productItems[0] || emptyItem)
  const [selectedSkus, setSelectedSkus] = useState<SelectPanelItemInput>(emptyItem)

  const [productSelectorOpen, setProductSelectorOpen] = useState(false)
  const [skuSelectorOpen, setSkuSelectorOpen] = useState(false)

  const [filterProduct, setFilterProduct] = useState('')

  const filteredProductItems = (budgetType === 'SkuPricing' ? skuPricingProductItems : productItems).filter(
    item => item.text === selectedProduct?.text || item.text?.toLowerCase().startsWith(filterProduct.toLowerCase()),
  )
  const selectedProductsSortedFirst = filteredProductItems.sort((a, b) => {
    if (a.text === selectedProduct?.text) return -1
    if (b.text === selectedProduct?.text) return 1
    return 0
  })

  // For SkuPricing, only show SKUs for products with >1 SKU
  const filteredSkus = skuItems.filter(item => {
    const skuProduct = skus.find(sku => sku.friendlyName === item.text)?.product
    const selectedProductName = Object.entries(PRODUCT_TAB_TEXT_MAP).find(
      ([_, value]) => value === selectedProduct?.text,
    )?.[0]
    const matchesSelectedProduct = skuProduct === selectedProductName
    return matchesSelectedProduct
  })

  const selectedSkuItemsSortedFirst = filteredSkus.sort((a, b) => {
    if (a.text === selectedSkus?.text) return -1
    if (b.text === selectedSkus?.text) return 1
    return 0
  })
  const handleProductSelection = (product: SelectPanelItemInput | undefined) => {
    if (!product) return
    setSelectedProduct(product)
    setBudgetValue(Object.entries(PRODUCT_TAB_TEXT_MAP).find(([_, value]) => value === product.text)?.[0] || '')
    setBudgetType('ProductPricing')
    setSelectedSkus(emptyItem)
  }
  const handleProductSelectionForSkuPanel = (product: SelectPanelItemInput | undefined) => {
    if (!product) return
    setSelectedProduct(product)
    setSelectedSkus(emptyItem)
    setBudgetValue('')
    setSkuFilter(product.text || '')
  }

  const handleSkuSelection = (sku: SelectPanelItemInput | undefined) => {
    if (!sku) return
    setSelectedSkus(sku)
    setBudgetValue(skus.find(s => s.friendlyName === sku.text)?.sku || '')
    setBudgetType('SkuPricing')
  }

  return (
    <div>
      <Heading as="h2" className={styles.Heading} aria-label="Budget type">
        Budget type
      </Heading>
      <RadioGroup
        name="budget-product-choices"
        aria-labelledby="budget-product-choices"
        onChange={selection => {
          if (selection) {
            setBudgetType(selection)
            if (selection === 'BundlePricing') {
              setBudgetValue('premium_requests')
              setSelectedProduct({id: 'premium_requests', text: 'premium_requests'})
              setSelectedSkus(emptyItem)
              setSkuFilter('premium_requests')
            } else {
              setBudgetValue(productItems[0]?.text || '') // Reset budgetValue when the radio button changes
              setSelectedProduct(productItems[0] || emptyItem)
              setSelectedSkus(emptyItem)
              setSkuFilter(productItems[0]?.text || '')
            }
          }
        }}
      >
        <div className={styles.BudgetSubTitleBox}>
          <span>Set budget for either a product or individual SKU within a product.</span>
        </div>
        <div className="Box">
          <div key="ProductPricing" className="Box-row">
            <FormControl className={styles.FlexContainerHorizontal}>
              <Radio value="ProductPricing" name="ProductPricing" checked={budgetType === 'ProductPricing'} />
              <FormControl.Label>
                Product-level budget
                {budgetType === 'ProductPricing' && (
                  <SelectPanelWrapper
                    label="Product"
                    showLabel={false}
                    showLeadingVisual
                    items={selectedProductsSortedFirst}
                    selected={selectedProduct}
                    onSelectedChange={handleProductSelection}
                    onFilterChange={setFilterProduct}
                    open={productSelectorOpen}
                    setOpen={setProductSelectorOpen}
                    placeholderText="Search"
                    title="Select 1 product"
                  />
                )}
                {budgetValue === 'models' && showModelsBillingError && <ModelsBillingErrorMessage />}
              </FormControl.Label>
            </FormControl>
          </div>
          <div key="SkuPricing" className="Box-row">
            <FormControl className={styles.FlexContainerHorizontal}>
              <Radio value="SkuPricing" name="SkuPricing" checked={budgetType === 'SkuPricing'} />
              <FormControl.Label>
                SKU-level budget
                {budgetType === 'SkuPricing' && (
                  <>
                    <SelectPanelWrapper
                      label="Product"
                      showLabel
                      showLeadingVisual
                      items={selectedProductsSortedFirst}
                      selected={selectedProduct}
                      onSelectedChange={handleProductSelectionForSkuPanel}
                      onFilterChange={setFilterProduct}
                      open={productSelectorOpen}
                      setOpen={setProductSelectorOpen}
                      title="Select 1 product"
                      placeholderText="Search"
                    />
                    <SelectPanelWrapper
                      label="SKU"
                      showLabel
                      showLeadingVisual={false}
                      items={selectedSkuItemsSortedFirst}
                      selected={selectedSkus}
                      onSelectedChange={handleSkuSelection}
                      onFilterChange={setSkuFilter}
                      open={skuSelectorOpen}
                      setOpen={setSkuSelectorOpen}
                      placeholderText="Search"
                    />
                    {showSkuError && selectedSkus?.text === '' && (
                      <InlineMessage variant="critical" className={styles.SKUErrorInlineMessage}>
                        SKU is required
                      </InlineMessage>
                    )}
                    {skuFilter === 'Models' && showModelsBillingError && <ModelsBillingErrorMessage />}
                  </>
                )}
              </FormControl.Label>
            </FormControl>
          </div>
          <div key="BundlePricing" className="Box-row">
            <FormControl className={styles.FlexContainerHorizontal}>
              <Radio value="BundlePricing" name="BundlePricing" checked={budgetType === 'BundlePricing'} />
              <FormControl.Label>
                Bundled premium requests budget <Label variant="done">New</Label>
                <p className={styles.BundleBudgetText}>
                  Set a budget for all SKUs that consume premium requests
                  {!isUserRoute ? (
                    <>
                      , where <BudgetCopilotPolicyLink isOrganizationRoute={isOrganizationRoute} />
                    </>
                  ) : (
                    '.'
                  )}
                </p>
                <span className={styles.BundleBudgetSubtext}>Supported SKUs:</span>
                <ul className={styles.BundleBudgetList}>
                  <li>Copilot premium requests</li>
                  <li>Coding Agent premium requests</li>
                  <li>Spark premium requests</li>
                </ul>
              </FormControl.Label>
            </FormControl>
          </div>
        </div>
      </RadioGroup>
    </div>
  )
}
