import type {ReactNode} from 'react'

import {LoadingComponent} from '..'
import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'

import {formatMoneyDisplay} from '../../utils/money'

import styles from './SummaryCardContainer.module.css'

interface Props {
  headerAction?: ReactNode
  heading: string
  description: string
  monetaryValue: number
  testId: string
  isLoading: boolean
}

export default function SummaryUsageCard({
  headerAction,
  heading,
  description,
  monetaryValue,
  testId,
  isLoading,
}: Props) {
  return (
    <div className={styles.card} data-testid={`${testId}-card`}>
      <div className={styles.header}>
        <p className={styles.heading}>{heading}</p>
        {headerAction}
      </div>
      <div className={isLoading ? styles.loadingMoneyDisplayContainer : styles.moneyDisplayContainer}>
        <div>
          {isLoading ? (
            <div className={styles.loadingComponentContainer}>
              <LoadingComponent className={styles.loadingComponentWrapper}>
                <LoadingSkeleton className={styles.loadingSkeleton} variant="rounded" height="xl" />
              </LoadingComponent>
            </div>
          ) : (
            <span className={styles.moneyDisplayText} data-testid={`${testId}-value`}>
              {formatMoneyDisplay(monetaryValue)}
            </span>
          )}
        </div>
      </div>
      <p className={styles.description} data-testid={`${testId}-description`}>
        {description}
      </p>
    </div>
  )
}
