import {Heading, Label} from '@primer/react'
import {formatMoneyDisplay} from '../../utils/money'
import {getDiscountLabel} from '../../utils/discount'
import styles from './PlanCard.module.css'
import type {CopilotForIndividualsData} from '../../types/copilot-for-individuals'

interface CopilotPlanCardProps {
  copilotForIndividualsData: CopilotForIndividualsData
}

export default function CopilotPlanCard({copilotForIndividualsData}: CopilotPlanCardProps) {
  const {onFreeTier, subscriptionItem} = copilotForIndividualsData

  const getProductName = (): string => {
    if (onFreeTier) {
      return 'Copilot Free'
    }
    switch (subscriptionItem?.name) {
      case 'GitHub Copilot Pro+':
        return 'Copilot Pro+'
      case 'GitHub Copilot Max':
        return 'Copilot Max'
      case 'GitHub Copilot Edu':
        return 'Copilot Student'
      default:
        return 'Copilot Pro'
    }
  }

  const getDisplayPrice = (): number => {
    if (subscriptionItem?.hasDiscount && subscriptionItem.discountedPrice != null) {
      return subscriptionItem.discountedPrice
    }
    if (subscriptionItem != null) {
      return subscriptionItem.price
    }
    return 0
  }

  const getBasePrice = (): number | null => {
    if (subscriptionItem?.hasDiscount && subscriptionItem.basePrice != null) {
      return subscriptionItem.basePrice
    }
    return null
  }

  const getBillingCycle = (): string => {
    if (subscriptionItem != null) {
      return subscriptionItem.billingCycle
    }
    return 'month'
  }

  const hasDiscount = subscriptionItem?.hasDiscount ?? false
  const basePrice = getBasePrice()
  const discountLabel = getDiscountLabel({
    hasDiscount,
    isPercentageDiscount: subscriptionItem?.isPercentageDiscount,
    discountPercentage: subscriptionItem?.discountPercentage,
    discountAmount: subscriptionItem?.discountAmount,
  })
  const couponDurationLabel = subscriptionItem?.couponDurationLabel

  return (
    <div className={styles.card} data-testid="copilot-plan-card">
      <div className={styles.planCard}>
        <div>
          <div className={styles.headingSection}>
            <Heading as="h3" className={styles.cardHeading}>
              {getProductName()}
            </Heading>
            {subscriptionItem?.hasPendingDowngrade && (
              <Label className={styles.downgradeLabel}>Downgrade Pending</Label>
            )}
          </div>
          <div className={styles.moneyContainer} data-testid="bill-section">
            <div>
              {hasDiscount && basePrice != null && (
                <span className={styles.strikethroughPrice}>
                  <span className="sr-only">Original price: </span>
                  {formatMoneyDisplay(basePrice, 2, true)}
                </span>
              )}
              <span className={styles.moneyAmount}>{formatMoneyDisplay(getDisplayPrice(), 2, true)}</span>
              <span className={styles.perPeriod}>per {getBillingCycle()}</span>
            </div>
          </div>
          {hasDiscount && discountLabel && (
            <div className={styles.discountLabel} data-testid="discount-label">
              <span className={styles.discountText}>
                ({discountLabel}
                {subscriptionItem?.couponWillExpire && couponDurationLabel && ` · ${couponDurationLabel} remaining`})
              </span>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
