import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'
import {XIcon} from '@primer/octicons-react'
import {IconButton} from '@primer/react'
import styles from './SelectedRows.module.css'

import type {Item} from '../../types/common'

interface Props<T> {
  loading?: boolean
  removeOption: (id: T) => void
  selected: Array<Item<T>>
  totalCount?: number
}

export function SelectedRows<T>({loading = false, removeOption, selected, totalCount}: Props<T>) {
  return (
    <div className={styles.container} data-testid="selected-rows-wrapper">
      <p className={styles.countText} data-testid="selected-rows-count">
        {totalCount && totalCount > 0 ? totalCount : selected.length} selected
      </p>
      <ul data-testid="selected-rows-list">
        {loading
          ? Array(totalCount)
              .fill(null)
              .map((_, idx) => (
                <li
                  // eslint-disable-next-line @eslint-react/no-array-index-key
                  key={idx}
                  className={styles.listItem}
                >
                  <LoadingSkeleton variant="rounded" className={styles.listItemSkeleton} />
                </li>
              ))
          : selected.map(item => (
              <li key={String(item.id)} className={styles.listItem}>
                {item.rowLeadingVisual()}
                <p className={styles.itemText}>{item.text}</p>
                {/* eslint-disable-next-line primer-react/a11y-remove-disable-tooltip */}
                <IconButton
                  unsafeDisableTooltip
                  icon={XIcon}
                  variant="invisible"
                  size="small"
                  onClick={() => removeOption(item.id)}
                  aria-label="Remove option"
                  style={{visibility: item.viewOnly ? 'hidden' : 'visible'}}
                />
              </li>
            ))}
      </ul>
    </div>
  )
}
