import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useParams} from '@github-ui/react-router'
// eslint-disable-next-line no-restricted-imports
import {useToastContext} from '@github-ui/toast/ToastContext'
import {useEffect, useState, useCallback} from 'react'
import {LinkButton, Text} from '@primer/styled-react'

import CreditsTable from '../../components/stafftools/credits/CreditsTable'
import Layout from '../../components/Layout'
import type {DiscountState} from '../../types/discounts'
import {isIncludedUsageDiscount} from '../../utils/discount'
import styles from './CreditsPage.module.css'

export interface CreditsPagePayload {
  discounts: DiscountState[]
  error?: string
}

export function CreditsPage() {
  const payload = useRoutePayload<CreditsPagePayload>()
  const {addToast} = useToastContext()
  const params = useParams<{business?: string; user?: string}>()

  // Determine if we're on a user or business page and construct appropriate path
  const newCreditPath = params.business
    ? `/stafftools/enterprises/${params.business}/billing/discounts`
    : `/stafftools/users/${params.user || ''}/billing/discounts`

  // Show toast when there's an error
  useEffect(() => {
    if (payload?.error) {
      // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
      addToast({
        type: 'error',
        message: `Error loading credits: ${payload.error}`,
        role: 'alert',
      })
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [payload?.error])

  const allDiscounts = payload?.discounts || []
  // Build credit items using the full DiscountState objects that have both currentAmount and DiscountDefinition
  const initialCreditItems: DiscountState[] = []
  const initialDeletedUuids = new Set<string>()

  for (const discountState of allDiscounts) {
    if (isIncludedUsageDiscount(discountState)) continue

    // Only include discount states that have a valid DiscountDefinition
    if (discountState.discount) {
      initialCreditItems.push(discountState)

      // Track credits that are already deleted from the server
      if (discountState.discount.deletedAt && discountState.discount.deletedAt !== 0) {
        initialDeletedUuids.add(discountState.discount.uuid)
      }
    }
  }

  const [creditItems, setCreditItems] = useState<DiscountState[]>(initialCreditItems)
  const [deletedUuids, setDeletedUuids] = useState<Set<string>>(() => initialDeletedUuids)

  // Update credit items when payload changes
  useEffect(() => {
    setCreditItems(initialCreditItems)
    // Reset deleted UUIDs to match server state
    setDeletedUuids(new Set(initialDeletedUuids))
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [payload?.discounts])

  /** marks credit as deleted with a given uuid */
  const deleteCreditFromPage = useCallback((uuid: string) => {
    setDeletedUuids(prev => new Set(prev).add(uuid))
  }, [])

  return (
    <Layout>
      <header className="Subhead">
        <h1 className={`Subhead-heading ${styles.PageHeading}`}>Credits</h1>
        <LinkButton href={newCreditPath} sx={{color: 'btn.text', ':hover': {textDecoration: 'none'}}}>
          <Text sx={{fontWeight: 'normal'}}>New credit</Text>
        </LinkButton>
      </header>
      {creditItems.length === 0 ? (
        <div className={styles.EmptyStateContainer}>
          <div className={styles.EmptyStateContent}>
            <h1 className={styles.EmptyStateHeading}>No credits found</h1>
            <p className={styles.EmptyStateText}>
              Credits and discounts applied to your organization will appear here.
            </p>
          </div>
        </div>
      ) : (
        <CreditsTable credits={creditItems} deletedUuids={deletedUuids} deleteCredit={deleteCreditFromPage} />
      )}
    </Layout>
  )
}
