import {use} from 'react'
import {Link} from '@primer/react'

import {PageContext} from '../../../App'
import PremiumUsageRequestsSummaryCard from './PremiumUsageRequestsSummaryCard'
import styles from './PremiumUsageRequestsSummaryCardContainer.module.css'
import useCopilotUsageCardData from '../../../hooks/usage/use-copilot-usage-card-data'
import {formatMoneyDisplay} from '../../../utils/money'
import useRoute from '../../../hooks/use-route'
import {BUDGETS_ROUTE} from '../../../routes'
import {getPeriodText} from '../../../utils/date'
import {UsagePeriod} from '../../../enums'

import type {Filters} from '../../../types/usage'

interface Props {
  filters: Filters
}

export default function PremiumUsageRequestsSummaryCardContainer({filters}: Props) {
  const {isEnterpriseRoute, isOrganizationRoute} = use(PageContext)
  const {path: budgetsUrl} = useRoute(BUDGETS_ROUTE)

  // isUserRoute from the page context returns true for organizations in stafftools as well
  // since they share the same base route. Checking that it's not an enterprise or organization route
  // allows stafftools to properly show organization specific content at the expense of user specific content.
  const isUserRoute = !isEnterpriseRoute && !isOrganizationRoute
  const userSearchQueryPresent = filters.searchQuery.includes('user:')

  const getDaysUntilReset = () => {
    const now = new Date()
    const nextMonth = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 1, 1))
    const timeDiff = nextMonth.getTime() - now.getTime()
    const daysRemaining = Math.ceil(timeDiff / (1000 * 3600 * 24))

    return daysRemaining === 1 ? '1 day' : `${daysRemaining} days`
  }

  // the reset date is currently always going to be the first of the month
  // this would change if we ever decide to reset based on the bill cycle days https://github.com/github/copilot/issues/20177
  const getResetDate = () => {
    const now = new Date()
    return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 1, 1))
  }

  const formattedResetDate = getResetDate().toLocaleDateString('default', {
    timeZone: 'UTC',
    month: 'long',
    day: 'numeric',
    year: 'numeric',
  })

  const {usageCardData, requestState: requestState} = useCopilotUsageCardData({filters})

  const billedAmountCardDescription = () => {
    if (isUserRoute) {
      return (
        <span>
          <Link inline href={budgetsUrl}>
            Increase your budget
          </Link>{' '}
          to use premium requests beyond your included request limit.
        </span>
      )
    } else {
      return `Spend for Copilot premium request usage for ${getPeriodText(filters.period)}.`
    }
  }

  const getMonthlyResetText = (isCurrentMonth: boolean, usePlural = true) => {
    if (!isCurrentMonth) return ''
    const limitText = usePlural ? 'limits reset' : 'limit resets'
    return ` Monthly ${limitText} in ${getDaysUntilReset()} on ${formattedResetDate}.`
  }

  const includedRequestsCardDescription = () => {
    const isCurrentMonth = filters.period?.type === UsagePeriod.THIS_MONTH

    if (isUserRoute) {
      return (
        <span>
          Premium requests included in your{' '}
          <Link inline href="/settings/copilot/features">
            Copilot plan
          </Link>
          {isCurrentMonth ? `.${getMonthlyResetText(isCurrentMonth, false)}` : '.'}
        </span>
      )
    }

    const baseText = userSearchQueryPresent
      ? 'Included premium requests used by selected user'
      : 'Included premium requests used by active Copilot users'

    return `${baseText}.${getMonthlyResetText(isCurrentMonth, true)}`
  }
  const isMonthlyRequest =
    filters.period?.type === UsagePeriod.THIS_MONTH || filters.period?.type === UsagePeriod.LAST_MONTH

  const shouldShowProgressBar = () => {
    if (!isMonthlyRequest) return false

    if (isUserRoute) {
      return !!usageCardData?.userPremiumRequestEntitlement
    }

    return userSearchQueryPresent && !!usageCardData?.filteredUserPremiumRequestEntitlement
  }

  const showProgressBar = shouldShowProgressBar()

  return (
    <div className={isUserRoute ? styles.userSummaryCardsGrid : styles.summaryCardsGrid}>
      <PremiumUsageRequestsSummaryCard
        title={isUserRoute ? 'Billed premium requests' : 'Total billed amount'}
        value={formatMoneyDisplay(usageCardData.netBilledAmount, 2, true)}
        description={billedAmountCardDescription()}
        testId="total-billed-amount-card"
        requestState={requestState}
      />
      {!isUserRoute && (
        <PremiumUsageRequestsSummaryCard
          title="Billed premium requests"
          value={usageCardData.netQuantity}
          description="Billed requests exceeding the premium requests usage included with Copilot licenses."
          testId="billable-premium-requests-card"
          requestState={requestState}
        />
      )}
      <PremiumUsageRequestsSummaryCard
        title="Included premium requests consumed"
        value={usageCardData.discountQuantity}
        description={includedRequestsCardDescription()}
        testId="included-premium-requests-card"
        requestState={requestState}
        showProgressBar={showProgressBar}
        entitlementValue={
          isUserRoute
            ? usageCardData?.userPremiumRequestEntitlement
            : usageCardData?.filteredUserPremiumRequestEntitlement
        }
      />
    </div>
  )
}
