import {Pagination, ActionList, Button} from '@primer/react'
import {useState, useEffect} from 'react'

import type {Item} from '../../types/common'
import pluralize from 'pluralize'
import styles from './ItemPicker.module.css'

type Props<T> = {
  items: Array<Item<T>>
  // The total number of available items. Sometimes this may be larger
  totalItemsCount: number
  initialSelected: Array<Item<T>>
  pickerType: string
  initialSelectAll: boolean
  onDialogSubmit: (newSelected: Array<Item<T>>, newSelectAll: boolean) => void
  selectionVariant?: 'single' | 'multiple'
  pageCount: number
  currentPage: number
  onPageChange: (event: React.MouseEvent, n: number) => void
  showPaginatedItems?: boolean
  /** Optional callback fired immediately when selection changes (for persisting across remounts) */
  onSelectionChange?: (newSelected: Array<Item<T>>) => void
}

export function ItemPicker<T>({
  items,
  totalItemsCount,
  initialSelected,
  initialSelectAll,
  pickerType,
  onDialogSubmit,
  selectionVariant,
  pageCount,
  currentPage,
  onPageChange,
  showPaginatedItems,
  onSelectionChange,
}: Props<T>) {
  const [selected, setSelected] = useState<Array<Item<T>>>(initialSelected || [])
  const [selectAll] = useState(initialSelectAll)

  const isSelected = (item: Item<T>) => selectAll || !!selected.find(i => i.id === item.id)
  const isDisabled = () => selectAll
  const shownItems = items.filter(item => !item.viewOnly)

  // Update notification whenever the filtered items change
  useEffect(() => {
    const liveRegion = document.getElementById('notification')

    /* Remove any existing child nodes */
    while (liveRegion?.firstChild) {
      liveRegion.removeChild(liveRegion.firstChild)
    }

    /* Create new message and append it to the live region */
    const messageText =
      items.length === 0
        ? `No ${pluralize(pickerType)} match this search`
        : `Showing ${shownItems.length} of ${totalItemsCount} ${pluralize(pickerType, totalItemsCount)}`
    const message = document.createTextNode(messageText)
    liveRegion?.appendChild(message)
  }, [shownItems.length, totalItemsCount, pickerType, items.length])

  const handleItemSelect = (item: Item<T>) => {
    if (!selectionVariant) return

    let newSelected: Array<Item<T>>
    if (selectionVariant === 'multiple') {
      newSelected = toggleMultiItem(item)
    } else {
      newSelected = [item]
    }
    setSelected(newSelected)
    onSelectionChange?.(newSelected)
  }

  const toggleMultiItem = (newItem: Item<T>): Array<Item<T>> => {
    const itemIndex = selected.findIndex(item => item.id === newItem.id)

    if (itemIndex === -1) {
      // Place the item after other editable items, but before any view-only items
      return [...selected.filter(item => !item.viewOnly), newItem, ...selected.filter(item => item.viewOnly)]
    } else {
      return selected.filter((_, index) => index !== itemIndex)
    }
  }

  return (
    <div>
      <div className={styles.listContainer}>
        <ActionList selectionVariant={selectionVariant} role="listbox" aria-label={`${pickerType} selector`}>
          {shownItems.map(item => (
            <ActionList.Item
              key={String(item.id)}
              role="option"
              disabled={isDisabled()}
              selected={isSelected(item)}
              aria-checked={isSelected(item)}
              onSelect={() => handleItemSelect(item)}
            >
              <ActionList.LeadingVisual>{item.leadingVisual()}</ActionList.LeadingVisual>
              {item.text}
            </ActionList.Item>
          ))}
        </ActionList>
        <div id="notification" aria-live="assertive" role="alert" className={styles.notification} />
      </div>
      <div className={styles.paginationContainer}>
        {showPaginatedItems && (
          <Pagination pageCount={pageCount} currentPage={currentPage} onPageChange={onPageChange} />
        )}
      </div>
      <div className={styles.footerContainer}>
        <Button
          variant="primary"
          data-testid={`select-${pickerType}-button`}
          onClick={() => {
            onDialogSubmit(selected, selectAll)
          }}
        >
          Select {pickerType}
        </Button>
      </div>
    </div>
  )
}
