import {useMemo} from 'react'
import {BUDGET_SCOPE_CUSTOMER, BUDGET_SCOPE_ENTERPRISE, BUDGET_SCOPE_MULTI_USER_CUSTOMER} from '../../constants'
import type {Budget} from '../../types/budgets'
import {BudgetType} from '../../enums/budgets'

const useFilteredBudgets = (
  budgets: Budget[],
  isOrganizationRoute: boolean,
  isUserRoute: boolean,
  isUserLevelBudgetManagementEnabled: boolean,
) => {
  return useMemo(() => {
    let customerBudgets: Budget[]
    let nonCustomerBudgets: Budget[]

    if (isOrganizationRoute || isUserRoute) {
      customerBudgets = budgets
        .filter(b => b.targetType === BUDGET_SCOPE_CUSTOMER) // TODO: remove 'Enterprise' after data migration
        .sort((a, b) => (a.targetName > b.targetName ? 1 : -1))
      nonCustomerBudgets = budgets
        .filter(b => b.targetType !== BUDGET_SCOPE_ENTERPRISE && b.targetType !== BUDGET_SCOPE_CUSTOMER) // TODO: remove 'Enterprise' after data migration
        .sort((a, b) => (a.targetName > b.targetName ? 1 : -1))
    } else {
      customerBudgets = budgets
        .filter(
          b =>
            b.targetType === BUDGET_SCOPE_CUSTOMER ||
            b.targetType === BUDGET_SCOPE_ENTERPRISE ||
            b.targetType === BUDGET_SCOPE_MULTI_USER_CUSTOMER,
        ) // TODO: remove 'Enterprise' after data migration
        .sort((a, b) => (a.targetName > b.targetName ? 1 : -1))
      nonCustomerBudgets = budgets
        .filter(
          b =>
            b.targetType !== BUDGET_SCOPE_CUSTOMER &&
            b.targetType !== BUDGET_SCOPE_ENTERPRISE &&
            b.targetType !== BUDGET_SCOPE_MULTI_USER_CUSTOMER,
        ) // TODO: remove 'Enterprise' after data migration
        .sort((a, b) => (a.targetName > b.targetName ? 1 : -1))
    }

    // filter for user-level budgets - these are launching with api access only at first, so removing them from the UI for now
    const userBudgetFilter = (b: Budget) =>
      (isUserLevelBudgetManagementEnabled &&
        (b.targetType === BudgetType.MULTI_USER_CUSTOMER || b.targetType === BudgetType.USER)) ||
      (b.targetType !== BudgetType.USER && b.targetType !== BudgetType.MULTI_USER_CUSTOMER)

    customerBudgets = customerBudgets.filter(userBudgetFilter)
    nonCustomerBudgets = nonCustomerBudgets.filter(userBudgetFilter)

    return {customerBudgets, nonCustomerBudgets}
  }, [budgets, isOrganizationRoute, isUserRoute, isUserLevelBudgetManagementEnabled])
}

export default useFilteredBudgets
