import {Banner, Heading, TextInput, FormControl, Checkbox} from '@primer/react'
import {Box} from '@primer/styled-react'
import {use, useEffect, useMemo, useState, useCallback, useRef} from 'react'

import {PageContext} from '../../App'
import {BudgetLimitTypes} from '../../enums/budgets'
import styles from './BudgetAmount.module.css'
import type {Product} from '../../types/products'
import type {PricingDetails} from '../../types/pricings'
import type {Filters, CustomerSelection} from '../../types/usage'
import useNetUsageData from '../../hooks/usage/use-net-usage-data'
import {useBillableLicenses} from '../../hooks/use-billable-licenses'
import {UsagePeriod} from '../../enums'
import type {Customer} from '../../types/common'
import {useBudgetProduct} from './hooks/use-budget-product'
import {useLicenseCalculations} from './hooks/use-license-calculations'
import {LicenseDisplay} from './components/LicenseDisplay'
import {formatMoneyDisplay} from '../../utils'
import {BUDGET_SCOPE_MULTI_USER_CUSTOMER, BUDGET_SCOPE_USER} from '../../constants'

interface Props {
  budgetAmount: number | string
  budgetLimitType: BudgetLimitTypes
  setBudgetAmount: (budgetAmount: number | string) => void
  setBudgetLimitType: (budgetLimitType: BudgetLimitTypes) => void
  action: 'create' | 'edit'
  budgetValue: string
  enabledProducts: Product[]
  enabledSkus: PricingDetails[]
  customer: Customer
  onValidationChange?: (hasError: boolean) => void
  budgetTargetType: string
  initialAmount?: number
}

export function BudgetAmount({
  budgetAmount,
  budgetLimitType,
  budgetTargetType,
  setBudgetAmount,
  setBudgetLimitType,
  action,
  budgetValue,
  enabledSkus,
  enabledProducts,
  customer,
  onValidationChange,
  initialAmount,
}: Props) {
  const isStafftoolsRoute = use(PageContext).isStafftoolsRoute

  const {selectedBudgetProduct, isHighWatermark, isCopilotProduct, canCreateLicenseSkuHardBudget} = useBudgetProduct({
    budgetValue,
    enabledSkus,
    enabledProducts,
  })

  const customer_selection: CustomerSelection = useMemo(
    () => ({
      id: customer.customerId,
      displayText: customer.name || customer.customerId,
    }),
    [customer.customerId, customer.name],
  )

  const filters: Filters = useMemo(
    () => ({
      customer: customer_selection,
      group: undefined,
      period: {
        type: UsagePeriod.THIS_MONTH,
        displayText: 'Current month',
      },
      product: selectedBudgetProduct?.productType,
      sku: selectedBudgetProduct?.isSku ? selectedBudgetProduct.identifier : '',
      searchQuery: '',
    }),
    [customer_selection, selectedBudgetProduct],
  )

  const {netUsage} = useNetUsageData({filters})
  const today = new Date()
  const billableLicenses = Math.ceil(useBillableLicenses({netUsage, filters, today}))
  const [validationMessage, setValidationMessage] = useState('')
  const isUniversalBudget = budgetTargetType === BUDGET_SCOPE_MULTI_USER_CUSTOMER
  const isUserBudget = budgetTargetType === BUDGET_SCOPE_USER
  const shouldForceStopUsage = isUniversalBudget || isUserBudget
  const minLicenseCount = useMemo(() => {
    return isHighWatermark && !isCopilotProduct && billableLicenses > 0 ? billableLicenses : 0
  }, [isHighWatermark, isCopilotProduct, billableLicenses])

  const validateLicenseCount = useCallback(
    (value: number | string) => {
      if (isHighWatermark && !isCopilotProduct) {
        const numericValue = typeof value === 'string' ? Number(value) : value
        if (!isNaN(numericValue) && numericValue < minLicenseCount) {
          setValidationMessage(`Count cannot be less than ${minLicenseCount.toLocaleString()}`)
          onValidationChange?.(true)
          return false
        }
      }
      setValidationMessage('')
      onValidationChange?.(false)
      return true
    },
    [isHighWatermark, isCopilotProduct, minLicenseCount, onValidationChange],
  )

  const handleChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const value = e.target.value

      if (e.type !== 'blur') {
        if (value === '' || !isNaN(Number(value))) {
          setBudgetAmount(value === '' ? value : Number(value))
          if (value !== '') {
            validateLicenseCount(Number(value))
          } else {
            setValidationMessage('')
          }
        }
      } else if (value === '') {
        setBudgetAmount(0)
        validateLicenseCount(0)
      } else {
        validateLicenseCount(Number(value))
      }
    },
    [setBudgetAmount, validateLicenseCount],
  )

  const {budgetDollarAmount, shouldShowLicenseCount} = useLicenseCalculations({
    budgetAmount,
    selectedBudgetProduct,
    isCopilotProduct,
  })

  // Track the previous budgetValue to only reset amount when the product actually changes
  const prevBudgetValueRef = useRef(budgetValue)

  // Prefill or reset license count based on product type during budget creation
  useEffect(() => {
    if (action === 'create') {
      const productChanged = prevBudgetValueRef.current !== budgetValue
      prevBudgetValueRef.current = budgetValue

      // Skip reset on initial mount when an initialAmount was provided from URL params
      if (!productChanged && initialAmount !== undefined && initialAmount > 0) {
        return
      }

      if (isHighWatermark && !isCopilotProduct && billableLicenses > 0) {
        // Prefill with current billable licenses for high watermark products, rounded up to next whole number
        setBudgetAmount(billableLicenses)
      } else {
        setBudgetAmount(0)
      }
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setValidationMessage('')
      onValidationChange?.(false)
    }
  }, [
    action,
    isHighWatermark,
    isCopilotProduct,
    billableLicenses,
    setBudgetAmount,
    onValidationChange,
    budgetValue,
    initialAmount,
  ])

  const getSkuPriceCaption = () => {
    if (
      isCopilotProduct ||
      !isHighWatermark ||
      !selectedBudgetProduct ||
      !selectedBudgetProduct.price ||
      !selectedBudgetProduct.friendlyName
    )
      return null

    return `$${selectedBudgetProduct.price}/license per month for ${selectedBudgetProduct.friendlyName}`
  }

  const renderLicenseDisplay = () => {
    if (!shouldShowLicenseCount || !selectedBudgetProduct?.price) return null

    return <LicenseDisplay budgetDollarAmount={budgetDollarAmount} />
  }

  const toggleBudgetLimitType = () => {
    if (budgetLimitType === BudgetLimitTypes.AlertingOnly) {
      setBudgetLimitType(BudgetLimitTypes.PreventFurtherUsage)
    } else {
      setBudgetLimitType(BudgetLimitTypes.AlertingOnly)
    }
  }

  const getStopBudgetText = () => {
    if (shouldForceStopUsage) return 'User spending will not exceed your set per user budget.'
    if (isHighWatermark) {
      return canCreateLicenseSkuHardBudget
        ? 'Additional usage will be limited once your budget is reached'
        : 'Not available for license-based products'
    }
    return "Spending won't exceed your set budget"
  }

  const getCheckboxLabel = () => {
    if (shouldForceStopUsage) return "Stop usage when user's budget limit is reached"
    if (isHighWatermark && canCreateLicenseSkuHardBudget) return 'Limit usage when budget limit is reached'
    return 'Stop usage when budget limit is reached'
  }

  return (
    <>
      <div>
        <Heading as="h2" className={styles.Heading}>
          Budget
        </Heading>
        <div className={styles.SubTitle}>
          <span>Set a budget amount to track your spending on a monthly basis.</span>
        </div>

        {action === 'create' && (
          <Banner data-testid="budget-usage-banner" title="budget-usage-banner" hideTitle className={styles.Banner}>
            <span>Usage before budget creation isn&apos;t counted in the current billing cycle.</span>
          </Banner>
        )}
        <div className="Box">
          <div className="Box-row">
            <Heading as="h4" className={styles.BudgetAmountHeading}>
              {isHighWatermark && !isCopilotProduct ? 'License count' : 'Budget amount'}
            </Heading>
            <div>
              <Box sx={{display: 'flex', fontSize: 1}}>
                <FormControl>
                  <FormControl.Label visuallyHidden>BudgetAmountInput</FormControl.Label>
                  <TextInput
                    inputMode="numeric"
                    pattern="^[0-9]+$" // only allow numbers
                    maxLength={10}
                    leadingVisual={isHighWatermark && !isCopilotProduct ? undefined : '$'}
                    className={`mt-1 ${isHighWatermark && !isCopilotProduct ? styles.LicenseCountInput : ''}`}
                    data-testid="budget-amount-input"
                    placeholder={
                      isHighWatermark && !isCopilotProduct && billableLicenses > 0
                        ? `${billableLicenses.toLocaleString()}`
                        : '0'
                    }
                    value={budgetAmount}
                    onChange={handleChange}
                    onBlur={handleChange}
                    name="budget-amount"
                    validationStatus={validationMessage ? 'error' : undefined}
                  />
                  {validationMessage && (
                    <FormControl.Validation variant="error">{validationMessage}</FormControl.Validation>
                  )}
                  {isCopilotProduct && (
                    <FormControl.Caption>
                      Budget amount will encompass both license costs and premium requests costs
                    </FormControl.Caption>
                  )}
                  {getSkuPriceCaption() && <FormControl.Caption>{getSkuPriceCaption()}</FormControl.Caption>}
                </FormControl>
                {isUniversalBudget && <span className="mt-2 ml-2">per user</span>}
                {isHighWatermark && <div className="mt-2 ml-2">{renderLicenseDisplay()}</div>}
              </Box>
              <div className="mt-2">
                {isUniversalBudget && selectedBudgetProduct?.price != null && (
                  <span style={{color: 'var(--fgColor-muted)', fontWeight: 'var(--base-text-weight-normal)'}}>
                    {Number(budgetAmount) / selectedBudgetProduct.price} premium requests (
                    {formatMoneyDisplay(selectedBudgetProduct.price)}/request)
                  </span>
                )}
              </div>

              <>
                <FormControl
                  className="tmp-mt-3"
                  disabled={
                    isStafftoolsRoute || (isHighWatermark && !canCreateLicenseSkuHardBudget) || shouldForceStopUsage
                  }
                >
                  <Checkbox
                    onChange={() => toggleBudgetLimitType()}
                    checked={budgetLimitType === BudgetLimitTypes.PreventFurtherUsage}
                    name="alert-checkbox"
                    data-testid="alert-checkbox"
                  />
                  <FormControl.Label>{getCheckboxLabel()}</FormControl.Label>
                  <FormControl.Caption>{getStopBudgetText()}</FormControl.Caption>
                </FormControl>
              </>
            </div>
          </div>
        </div>
      </div>
    </>
  )
}
