import {Link, Label} from '@primer/react'

import {formatMoneyDisplay} from '../../utils/money'
import {PAYMENT_HISTORY_ROUTE} from '../../routes'
import useRoute from '../../hooks/use-route'

import type {PaymentDueCardProps} from './PaymentDueCard'

import styles from '../usage/SummaryCardContainer.module.css'

export default function AutoPayEnabledCard(props: PaymentDueCardProps) {
  const {path: paymentHistoryRoute} = useRoute(PAYMENT_HISTORY_ROUTE)

  return (
    <div className={styles.card} data-testid="auto-pay-enabled-payment-due-card">
      <div className={styles.header}>
        <p className={styles.heading}>Past due</p>

        <Link href={paymentHistoryRoute} className={styles.link} inline>
          Payment history
        </Link>
      </div>

      <div className={styles.paymentContainer}>
        <div>
          <p className={styles.moneyDisplayText}>{formatMoneyDisplay(props.latestBillAmount)}</p>
        </div>
        <div>{props.overdue && <Label variant="attention">Overdue</Label>}</div>
      </div>

      <div className={styles.paymentDueContainer}>
        {props.meteredViaAzure && <p>Metered usage billed via Azure is not included.</p>}
        <p>
          {props.nextPaymentDate ? (
            <>
              Your next payment is scheduled for <span className={styles.paymentDate}>{props.nextPaymentDate}.</span>
            </>
          ) : (
            <>No upcoming payment scheduled.</>
          )}
        </p>
      </div>
    </div>
  )
}
