import {ErrorBoundary} from '@github-ui/react-core/error-boundary'
import {Heading} from '@primer/react'
import {useEffect, useMemo, useState, useTransition} from 'react'
import {useQueryLoader, fetchQuery, useRelayEnvironment, readInlineData, type Environment} from 'react-relay'
import {Observable} from 'relay-runtime'

import {ResourceType} from '../../enums/cost-centers'

import {BILLING_MANAGER, OWNER} from '../../constants'
import {ErrorBanner} from '../common/ErrorBanner'
import type {User} from '../pickers/UserPicker'
import {
  UserPicker,
  UserPickerSearchQuery,
  UserPickerInitialUsersQuery,
  UserPickerInitialUsersByRoleQuery,
  UserPickerUserFragment,
} from '../pickers/UserPicker'
import type {UserPickerSearchQuery as UserPickerSearchQueryType} from '../pickers/__generated__/UserPickerSearchQuery.graphql'
import type {
  UserPickerInitialUsersQuery$data,
  UserPickerInitialUsersQuery as UserPickerInitialUsersQueryType,
} from '../pickers/__generated__/UserPickerInitialUsersQuery.graphql'
import type {
  UserPickerInitialUsersByRoleQuery$data,
  UserPickerInitialUsersByRoleQuery as UserPickerInitialUsersByRoleQueryType,
} from '../pickers/__generated__/UserPickerInitialUsersByRoleQuery.graphql'
import type {UserPickerUserFragment$key} from '../pickers/__generated__/UserPickerUserFragment.graphql'

import type {AdminRole, Customer} from '../../types/common'
import type {CostCenterPicker, Resource} from '../../types/cost-centers'
import {PickerLoadingSkeleton} from '../pickers/PickerLoadingSkeleton'
import {OrganizationPickerParentGraphqlQuery, PaginatedOrganizationPicker} from '../pickers/PaginatedOrganizationPicker'
import type {PaginatedOrganizationPickerGraphqlQuery} from '../pickers/__generated__/PaginatedOrganizationPickerGraphqlQuery.graphql'
import type {PaginatedRepositoryPickerGraphqlQuery} from '../pickers/__generated__/PaginatedRepositoryPickerGraphqlQuery.graphql'
import {
  PaginatedRepositoryPicker,
  PaginatedRepositoryPickerParentGraphqlQuery,
} from '../pickers/PaginatedRepositoryPicker'
import CostCenterApiTile from './CostCenterApiTile'

import styles from './CostCenterResourceSelector.module.css'

interface Props {
  adminRoles: AdminRole[]
  customer: Customer
  resources: Resource[]
  setCostCenterResources: (resources: Resource[]) => void
  // Optionally disable the org or repo picker or both
  disablePicker?: CostCenterPicker[]
  // Optionally display the resource selector in view-only mode
  viewOnly?: boolean
}

function useFetchPaginatedOrganizations(customer: Customer, {disabled}: {disabled: boolean}) {
  const [, startTransition] = useTransition()
  const [paginatedOrganizationsRef, loadPaginatedOrganizations, disposePaginatedOrganizationsRef] =
    useQueryLoader<PaginatedOrganizationPickerGraphqlQuery>(OrganizationPickerParentGraphqlQuery)

  useEffect(() => {
    if (!disabled) {
      startTransition(() => {
        loadPaginatedOrganizations({slug: customer.displayId, query: null}, {fetchPolicy: 'store-or-network'})
      })
    }

    return () => disposePaginatedOrganizationsRef()
  }, [loadPaginatedOrganizations, disposePaginatedOrganizationsRef, disabled, customer.displayId])

  return paginatedOrganizationsRef
}

function useFetchPaginatedRepositories(customer: Customer, {disabled}: {disabled: boolean}) {
  const [, startTransition] = useTransition()
  const [paginatedRepositoriesRef, loadPaginatedRepositories, disposePaginatedRepositoriesRef] =
    useQueryLoader<PaginatedRepositoryPickerGraphqlQuery>(PaginatedRepositoryPickerParentGraphqlQuery)

  useEffect(() => {
    if (!disabled) {
      startTransition(() => {
        loadPaginatedRepositories({slug: customer.displayId}, {fetchPolicy: 'store-or-network'})
      })
    }
    return () => {
      disposePaginatedRepositoriesRef()
    }
  }, [loadPaginatedRepositories, disposePaginatedRepositoriesRef, disabled, customer.displayId])
  return paginatedRepositoriesRef
}

function useFetchUsers(customer: Customer, {disabled}: {disabled: boolean}) {
  const [, startTransition] = useTransition()
  const [usersRef, loadUsers, disposeUsersRef] = useQueryLoader<UserPickerSearchQueryType>(UserPickerSearchQuery)

  useEffect(() => {
    if (!disabled) {
      startTransition(() => {
        loadUsers({slug: customer.displayId}, {fetchPolicy: 'store-or-network'})
      })
    }

    return () => disposeUsersRef()
  }, [loadUsers, disposeUsersRef, disabled, customer.displayId])

  return usersRef
}

export function CostCenterResourceSelector({
  adminRoles,
  customer,
  resources,
  setCostCenterResources,
  disablePicker,
  viewOnly = false,
}: Props) {
  const [loadOrgsError, setLoadOrgsError] = useState<Error>()
  const [loadReposError, setLoadReposError] = useState<Error>()

  const isOrgPickerDisabled = !!disablePicker?.includes('org')
  const isRepoPickerDisabled = !!disablePicker?.includes('repo')
  const isUserPickerDisabled = !!disablePicker?.includes('user')

  const paginatedOrganizationsRef = useFetchPaginatedOrganizations(customer, {disabled: isOrgPickerDisabled})
  const paginatedRepositoriesRef = useFetchPaginatedRepositories(customer, {disabled: isRepoPickerDisabled})
  const usersRef = useFetchUsers(customer, {disabled: isUserPickerDisabled})

  const isAdmin = adminRoles.includes(OWNER) || adminRoles.includes(BILLING_MANAGER)

  function handleOrgsGQLError(e: Error) {
    setLoadOrgsError(e)
  }

  function handleReposGQLError(e: Error) {
    setLoadReposError(e)
  }

  // Fetch initial selected users for cost center
  const resourceByUser = useMemo(
    () => resources.filter(resource => resource.type === ResourceType.User).map(resource => resource.id),
    [resources],
  )
  const environment = useRelayEnvironment()
  const [initialUsers, setInitialUsers] = useState<User[]>([])

  useEffect(() => {
    if (!isUserPickerDisabled && usersRef && resourceByUser.length > 0) {
      const expectedUserIds = new Set(resourceByUser)
      let allFetchedUsers: User[] = []
      let completedChunks = 0

      const BATCH_SIZE = 100
      const chunks: string[][] = []
      for (let i = 0; i < resourceByUser.length; i += BATCH_SIZE) {
        chunks.push(resourceByUser.slice(i, i + BATCH_SIZE))
      }

      // Fetch user details in batches
      for (const idsChunk of chunks) {
        fetchUsersQuery(environment, {
          slug: customer.displayId,
          ids: idsChunk,
          limit: idsChunk.length,
          isAdmin,
        }).subscribe({
          next: (data: UserPickerInitialUsersQuery$data | UserPickerInitialUsersByRoleQuery$data) => {
            const nodes =
              'enterprise' in data && data.enterprise?.organizationsMembers?.nodes
                ? data.enterprise.organizationsMembers.nodes
                : 'nodes' in data && Array.isArray(data.nodes)
                  ? data.nodes
                  : []

            const users = nodes.flatMap(node =>
              // eslint-disable-next-line no-restricted-syntax
              node ? [readInlineData<UserPickerUserFragment$key>(UserPickerUserFragment, node)] : [],
            )

            allFetchedUsers = [...allFetchedUsers, ...users]
            completedChunks++

            // Only update when all chunks are complete
            if (completedChunks === chunks.length) {
              const uniqueUsers = [...expectedUserIds].map(
                (userId, _) =>
                  allFetchedUsers.find(user => user.id === userId) || ({id: userId, viewOnly: true} as User),
              )
              setInitialUsers(uniqueUsers)
            }
          },
          error: () => {
            completedChunks++
            // Still check completion even if some chunks failed
            if (completedChunks === chunks.length) {
              const uniqueUsers = [...expectedUserIds].map(
                (userId, _) =>
                  allFetchedUsers.find(user => user.id === userId) || ({id: userId, viewOnly: true} as User),
              )
              setInitialUsers(uniqueUsers)
            }
          },
        })
      }
    } else {
      setInitialUsers([])
    }
  }, [environment, resourceByUser, usersRef, customer.displayId, isAdmin, isUserPickerDisabled])

  const resourceByOrg = resources.filter(resource => resource.type === ResourceType.Org).map(resource => resource.id)
  const resourceByRepo = resources.filter(resource => resource.type === ResourceType.Repo).map(resource => resource.id)

  const filterByType = (selectedIds: string[], type: ResourceType) => {
    const tmp = resources.filter(item => item.type !== type)
    const newResources = selectedIds.map(item => {
      const resource: Resource = {type, id: String(item)}
      return resource
    })
    setCostCenterResources(tmp.concat(newResources))
  }

  const setOrgIds = (orgs: string[]) => {
    filterByType(orgs, ResourceType.Org)
  }

  const setRepoIds = (repos: string[]) => {
    filterByType(repos, ResourceType.Repo)
  }

  const handleUserChange = (users: User[]) => {
    const selectedUsers = users.filter(u => !!u.id).map(u => u.id)
    filterByType(selectedUsers, ResourceType.User)
  }

  return (
    <div className={styles.outerBox}>
      <div className={styles.resourcesHeaderBox}>
        <Heading as="h3" className={`h2-override-shared-component ${styles.resourcesHeading}`}>
          Resources
        </Heading>
        {!viewOnly && (
          <span>
            Set the resources that will be a part of this cost center. A maximum of 50 resources can be added or removed
            at a time.
          </span>
        )}
      </div>
      {!isOrgPickerDisabled && (
        <div className={`Box ${styles.pickerBox}`} data-testid="org-picker-wrapper">
          <ErrorBoundary onError={handleOrgsGQLError}>
            {paginatedOrganizationsRef ? (
              <PaginatedOrganizationPicker
                preloadedOrganizationsRef={paginatedOrganizationsRef}
                setSelectedItems={setOrgIds}
                initialSelectedItemIds={resourceByOrg}
                selectionVariant="multiple"
                indent={false}
                entityType="cost center"
                viewOnly={viewOnly}
              />
            ) : (
              <PickerLoadingSkeleton title="Organizations" totalCount={resourceByOrg.length} viewOnly={viewOnly} />
            )}
          </ErrorBoundary>
          {loadOrgsError && <ErrorBanner message={loadOrgsError.cause as string} sx={{mt: 2, mb: 0}} />}
        </div>
      )}
      {!isRepoPickerDisabled && (
        <div className={`Box ${styles.pickerBox}`} data-testid="repo-picker-wrapper">
          <ErrorBoundary onError={handleReposGQLError}>
            {paginatedRepositoriesRef ? (
              <PaginatedRepositoryPicker
                slug={customer.displayId}
                preloadedRepositoriesRef={paginatedRepositoriesRef}
                setSelectedItems={setRepoIds}
                initialSelectedItemIds={resourceByRepo}
                selectionVariant="multiple"
                indent={false}
                entityType="cost center"
                viewOnly={viewOnly}
              />
            ) : (
              <PickerLoadingSkeleton title="Repositories" totalCount={resourceByRepo.length} viewOnly={viewOnly} />
            )}
          </ErrorBoundary>
          {loadReposError && <ErrorBanner message={loadReposError.cause as string} sx={{mt: 2, mb: 0}} />}
        </div>
      )}
      {!isUserPickerDisabled ? (
        <div className={`Box ${styles.pickerBox}`} data-testid="user-picker-wrapper">
          <Heading as="h4" className={styles.usersHeading}>
            Users
          </Heading>
          <ErrorBoundary>
            {usersRef ? (
              <UserPicker
                viewOnly={viewOnly}
                slug={customer.displayId}
                onSelectionChange={handleUserChange}
                initialUsers={initialUsers} // initial selected users generated from cost center resources
                preloadedData={{
                  type: 'roleBasedMembers',
                  data: usersRef,
                }}
                itemType="users"
              />
            ) : (
              <PickerLoadingSkeleton title="" totalCount={resourceByUser.length} viewOnly={viewOnly} />
            )}
          </ErrorBoundary>
        </div>
      ) : (
        <CostCenterApiTile />
      )}
    </div>
  )
}

function fetchUsersQuery(
  environment: Environment,
  {
    isAdmin,
    slug,
    ids,
    limit,
  }: {
    isAdmin: boolean
    slug: string
    ids: string[]
    limit: number
  },
): Observable<UserPickerInitialUsersQuery$data | UserPickerInitialUsersByRoleQuery$data> {
  if (isAdmin) {
    return fetchQuery<UserPickerInitialUsersQueryType>(environment, UserPickerInitialUsersQuery, {
      ids,
    })
  } else {
    return fetchQuery<UserPickerInitialUsersByRoleQueryType>(environment, UserPickerInitialUsersByRoleQuery, {
      slug,
      ids,
      limit,
    })
  }
}
