import {SelectedRows} from './SelectedRows'
import {PickerHeader} from './PickerHeader'
import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'
import styles from './PickerLoadingSkeleton.module.css'

interface Props {
  title: string
  // Number of rows to render
  totalCount: number
  // Optionally display the resource selector in view-only mode
  viewOnly?: boolean
}

export function PickerLoadingSkeleton({title, totalCount, viewOnly = false}: Props) {
  return (
    <>
      <PickerHeader title={title} />
      <div>
        {!viewOnly && <LoadingSkeleton className={styles.skeletonButton} />}
        <SelectedRows loading removeOption={() => {}} selected={[]} totalCount={totalCount} />
      </div>
    </>
  )
}
