import last from 'lodash-es/last'
import type {ReactNode} from 'react'
import React, {useState, useMemo, use} from 'react'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
// eslint-disable-next-line no-restricted-imports
import {useToastContext} from '@github-ui/toast/ToastContext'
import {Button, Details, Select, useDetails, FormControl} from '@primer/react'

import {Dialog, Octicon} from '@primer/react/deprecated'
import {ChevronDownIcon, ChevronLeftIcon} from '@primer/octicons-react'

import {ErrorComponent} from '../../components'
import CostCenterSelector from '../../components/common/CostCenterSelector'
import {generateInvoiceRequest} from '../../services/invoices'
import useInvoices from '../../hooks/invoice/use-invoices'
import {formatDate} from '../../utils/date'
import {formatMoneyDisplay} from '../../utils/money'

import type {Invoice, GenerateInvoiceRequest} from '../../types/invoices'
import type {CustomerSelection} from '../../types/usage'
import {RequestState} from '../../enums'
import {PageContext} from '../../App'
import styles from './InvoicesPage.module.css'

type InvoiceRowProps = {
  invoice: Invoice
  idx: number
}

type Months = 'Jan' | 'Feb' | 'Mar' | 'Apr' | 'May' | 'Jun' | 'Jul' | 'Aug' | 'Sep' | 'Oct' | 'Nov' | 'Dec'

const months: Months[] = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

const InvoiceRow = ({invoice, idx}: InvoiceRowProps) => {
  const {getDetailsProps, open} = useDetails({closeOnOutsideClick: false})

  const rowSummary = (
    <tr key={idx} className={styles.sharedRow}>
      <td className={styles.tableCell}>
        <div className={styles.tableCellContent}>
          <span data-testid={`${idx}-invoice-date`} className={styles.textMedium}>
            {formatDate(invoice.year, invoice.month)}
          </span>
        </div>
      </td>

      <td className={styles.tableCell}>
        <div className={styles.tableCellContent}>
          <span className={styles.textMedium}>{formatMoneyDisplay(invoice.usageTotal.gross)}</span>
        </div>
      </td>
      <td className={styles.tableCell}>
        <div className={styles.tableCellContent}>
          <span className={styles.textMedium}>{formatMoneyDisplay(invoice.usageTotal.discount)}</span>
        </div>
      </td>
      <td className={styles.tableCell}>
        <div className={styles.tableCellContent}>
          <span className={styles.textMedium}>{formatMoneyDisplay(invoice.usageTotal.net)}</span>
        </div>
      </td>
      <td className={styles.tableCell}>
        <div className={styles.tableCellContent}>
          <span className={styles.textMedium}>{invoice.usageTotal.quantity}</span>
        </div>
      </td>

      <td className={styles.tableCell}>
        <Details {...getDetailsProps()} className={styles.Details}>
          <summary
            className={styles.summaryBox}
            aria-label={open ? 'Hide Invoice Breakdown' : 'Show Invoice Breakdown'}
            data-testid={'invoice-details'}
          >
            <Octicon icon={open ? ChevronDownIcon : ChevronLeftIcon} />
          </summary>
        </Details>
      </td>
    </tr>
  )

  return (
    <>
      {rowSummary}
      {open && (
        <tr key={`${idx}-detail`} className={styles.detailRow}>
          <td className={styles.detailCell} colSpan={7}>
            <pre className={styles.detailPre}>{JSON.stringify(invoice, null, 2)}</pre>
          </td>
        </tr>
      )}
    </>
  )
}

function InvoiceGeneration({slug, selectedCustomer}: {slug: string; selectedCustomer: CustomerSelection}) {
  const returnFocusRef = React.useRef(null)
  const [isOpen, setIsOpen] = useState<boolean | undefined>(false)
  const [currentDate, setCurrentDate] = useState<Date>(() => new Date())

  const currentMonth = currentDate.getMonth()
  const currentYear = currentDate.getFullYear()

  const isOrganizationRoute = use(PageContext).isOrganizationRoute
  const accountType = isOrganizationRoute ? 'users' : 'enterprises'

  const getMonthPicker = useMemo(() => {
    const monthElements: ReactNode[] = months.map((month, idx) => {
      return (
        <Select.Option key={month} value={`${idx}`}>
          {month}
        </Select.Option>
      )
    })

    return (
      <FormControl>
        <FormControl.Label style={{alignSelf: 'center'}}>Month</FormControl.Label>
        <Select
          value={currentMonth}
          aria-label="Month"
          onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {
            const newDate = new Date(currentYear, Number(e.target.value))
            setCurrentDate(newDate)
          }}
        >
          {monthElements}
        </Select>
      </FormControl>
    )
  }, [currentMonth, currentYear, setCurrentDate])

  const getYearPicker = useMemo(() => {
    const years: ReactNode[] = []
    const todaysYear = new Date().getFullYear()
    const minYear = todaysYear - 10
    const maxYear = todaysYear
    for (let i = minYear; i <= maxYear; i++) {
      years.push(
        <Select.Option key={i} value={`${i}`}>
          {i}
        </Select.Option>,
      )
    }

    return (
      <FormControl>
        <FormControl.Label style={{alignSelf: 'center'}}>Year</FormControl.Label>
        <Select
          value={currentYear}
          aria-label="Year"
          onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {
            const newDate = new Date(Number(e.target.value), currentMonth)

            setCurrentDate(newDate)
          }}
        >
          {years}
        </Select>
      </FormControl>
    )
  }, [currentMonth, currentYear, setCurrentDate])

  const {addToast} = useToastContext()

  async function generateInvoice() {
    const data: GenerateInvoiceRequest = {
      customerId: selectedCustomer.id,
      year: currentYear,
      month: currentMonth + 1, // currentMonth is 0 indexed but billing-platform expects months 1-12 so add 1
    }

    try {
      const {error} = await generateInvoiceRequest(slug, data, accountType)
      if (error) {
        // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
        addToast({
          type: 'error',
          message: `There was an issue generating your invoice ${error}`,
        })
      } else {
        // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
        addToast({
          type: 'success',
          message: 'Invoice scheduled for generation',
        })
      }
    } catch {
      // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
      addToast({
        type: 'error',
        message: 'Error generating invoice',
      })
    } finally {
      setIsOpen(false)
    }
  }

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault()

    await generateInvoice()
  }

  // Form
  return (
    <>
      <Button aria-label="Generate Invoice" size="small" ref={returnFocusRef} onClick={() => setIsOpen(true)}>
        Generate Invoice
      </Button>
      <Dialog
        isOpen={isOpen}
        returnFocusRef={returnFocusRef}
        onDismiss={() => setIsOpen(false)}
        aria-labelledby="label"
      >
        <Dialog.Header>
          <h3 className={styles.dialogHeading}>Generate invoice for {selectedCustomer.displayText}</h3>
        </Dialog.Header>
        <div className={styles.dialogContent}>
          <div className={styles.dialogSection}>
            <p id="label" className={styles.dialogText}>
              Populates an invoice for the given year and month.
            </p>
            <p className={`${styles.dialogSubtle} text-small`}>
              &bull; An invoice won&apos;t be generated if there&apos;s no usage for the given period or if the customer
              is enabled for daily emissions.
            </p>
            <p className={`${styles.dialogSubtle} text-small`}>
              &bull; If there is an existing invoice for the period, it will be updated.
            </p>
          </div>
          <form onSubmit={handleSubmit}>
            <div className={styles.formRow}>
              {getMonthPicker}
              {getYearPicker}
            </div>
            <div className={styles.formActions}>
              <Button type="submit" variant="primary">
                Generate
              </Button>
            </div>
          </form>
        </div>
      </Dialog>
    </>
  )
}

export interface InvoicesPagePayload {
  customerSelections: CustomerSelection[]
  slug: string
  error?: string
}

export function InvoicesPage() {
  const {customerSelections, slug} = useRoutePayload<InvoicesPagePayload>()

  const [selectedCustomer, setSelectedCustomer] = useState<CustomerSelection>(
    () => last(customerSelections) as CustomerSelection,
  )

  const {invoices, requestState} = useInvoices({enterpriseSlug: slug, customerId: selectedCustomer?.id})

  const header = (
    <header className={`Subhead ${styles.header}`}>
      <CostCenterSelector
        getHeadingText={(sc: CustomerSelection) => {
          return `Invoices for ${sc.displayText}`
        }}
        selections={customerSelections}
        selectedCustomer={selectedCustomer}
        setSelectedCustomer={setSelectedCustomer}
        title={`View invoices for`}
        as={'h2'}
      />
      <InvoiceGeneration selectedCustomer={selectedCustomer} slug={slug} />
    </header>
  )

  if (requestState === RequestState.ERROR) {
    return (
      <div>
        {header}
        <ErrorComponent testid="invoices-loading-error" text="Something went wrong" />
      </div>
    )
  }

  if (invoices.length === 0) {
    return (
      <div>
        {header}
        <div className={styles.emptyState}>No invoices found</div>
      </div>
    )
  }

  return (
    <div>
      {header}
      <InvoicesTableView invoices={invoices} />
    </div>
  )
}

/** Presentational component for rendering the invoices table - useful for Storybook */
export interface InvoicesTableViewProps {
  invoices: Invoice[]
}

export function InvoicesTableView({invoices = []}: InvoicesTableViewProps) {
  if (invoices.length === 0) {
    return <div className={styles.emptyState}>No invoices found</div>
  }

  return (
    <div className={styles.tableContainer}>
      <table className={styles.table} data-hpc>
        <thead>
          <tr>
            <th className={styles.tableHeader}>Date</th>
            <th className={styles.tableHeader}>Gross</th>
            <th className={styles.tableHeader}>Discount</th>
            <th className={styles.tableHeader}>Net</th>
            <th className={styles.tableHeader}>Quantity</th>
            <th className={styles.tableHeaderLastCell}>Details</th>
          </tr>
        </thead>
        <tbody>
          {invoices.map((invoice, idx) => {
            // eslint-disable-next-line @eslint-react/no-array-index-key
            return <InvoiceRow invoice={invoice} idx={idx} key={idx} />
          })}
        </tbody>
      </table>
    </div>
  )
}
