import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'
import {Label, Link} from '@primer/react'
import {use} from 'react'

import {ErrorComponent} from '..'
import {RequestState, UsagePeriod} from '../../enums'
import {formatMoneyDisplay} from '../../utils/money'
import useRoute from '../../hooks/use-route'
import {
  LICENSING_BASE_ROUTE,
  ENTERPRISE_LICENSING_COPILOT_BASE_ROUTE,
  USAGE_ROUTE,
  PREMIUM_REQUESTS_USAGE_ROUTE,
  AI_USAGE_ROUTE,
} from '../../routes'
import {GROUP_BY_SKU_TYPE, Products} from '../../constants'
import type {Filters} from '../../types/usage'
import {PageContext} from '../../App'

import styles from './UsageInfoTile.module.css'
import utilitiesStyles from '../utilities.module.css'

export const UsageInfoTileVariant = {
  quantity: 'QUANTITY',
  money: 'MONEY',
} as const

export const UsageInfoTileTypes = {
  copilotUsage: 'COPILOT',
  copilotLicenses: 'COPILOT_LICENSES',
  copilotPremiumRequests: 'COPILOT_PREMIUM_REQUESTS',
  copilotAiCredits: 'COPILOT_AI_CREDITS',
  models: 'MODELS',
  generalAmount: 'GENERAL_AMOUNT',
  generalLicenses: 'GENERAL_LICENSES',
} as const

export type UsageInfoTileVariant = (typeof UsageInfoTileVariant)[keyof typeof UsageInfoTileVariant]
export type UsageInfoTileType = (typeof UsageInfoTileTypes)[keyof typeof UsageInfoTileTypes]

interface UsageInfoTileProps {
  filters: Filters
  isCopilotStandalone: boolean
  productName: string
  requestState: RequestState
  totalSpend?: number
  totalQuantity?: number
  variant: UsageInfoTileVariant
  infoIconOverlay?: React.ReactNode
  showTrial?: boolean
  title: string
  subtitle: string
  tileType: string
}

const isLoadingStates = new Set<RequestState>([RequestState.INIT, RequestState.LOADING])

export default function UsageInfoTile({
  filters,
  isCopilotStandalone,
  productName,
  requestState,
  totalSpend = 0,
  totalQuantity = 0,
  variant,
  infoIconOverlay,
  showTrial = false,
  title,
  subtitle,
  tileType,
}: UsageInfoTileProps) {
  const {path: usageUrl} = useRoute(
    USAGE_ROUTE,
    {},
    {
      group: GROUP_BY_SKU_TYPE.toString(),
      period: filters?.period?.type?.toString() ?? UsagePeriod.DEFAULT.toString(),
      query: `product:${filters.product}`,
    },
  )
  const {path: licensingUrl} = useRoute(LICENSING_BASE_ROUTE)
  const {path: enterpriseLicensingCopilotUrl} = useRoute(ENTERPRISE_LICENSING_COPILOT_BASE_ROUTE)
  const {path: premiumRequestUsageUrl} = useRoute(PREMIUM_REQUESTS_USAGE_ROUTE)
  const {path: aiCreditsUsageUrl} = useRoute(AI_USAGE_ROUTE)
  const {isEnterpriseRoute} = use(PageContext)

  function spotlightedValue() {
    if (showTrial) {
      return 'This product is currently in a free trial period.'
    }
    if (variant === UsageInfoTileVariant.money) {
      return formatMoneyDisplay(totalSpend)
    }
    return totalQuantity.toLocaleString('default', {maximumFractionDigits: 0})
  }

  function viewDetailsLink() {
    // Special case for Copilot billable licenses on enterprise routes - show "Manage" link
    if (isEnterpriseRoute && tileType === UsageInfoTileTypes.copilotLicenses) {
      return (
        <Link className="ml-auto" href={enterpriseLicensingCopilotUrl} inline>
          Manage
        </Link>
      )
    }

    if (variant === UsageInfoTileVariant.quantity && filters.product === Products.copilot && !isCopilotStandalone) {
      return null
    }

    const getViewDetailsUrl = () => {
      if (tileType === UsageInfoTileTypes.copilotAiCredits) {
        return aiCreditsUsageUrl
      }

      if (filters.product === Products.copilot && tileType === UsageInfoTileTypes.copilotPremiumRequests) {
        return premiumRequestUsageUrl
      }

      if (variant === UsageInfoTileVariant.money) {
        return usageUrl
      }

      return licensingUrl
    }

    const url = getViewDetailsUrl()

    return (
      <Link className="ml-auto" href={url} inline>
        View details
      </Link>
    )
  }

  return (
    <div className={styles.usageBoxStyle}>
      <div className={styles.header}>
        <p className={styles.usageHeading}>{title}</p>
        {showTrial && (
          <Label variant="accent" data-testid="summary-card-label-trial">
            Trial
          </Label>
        )}
        {infoIconOverlay}
        {viewDetailsLink()}
      </div>
      {isLoadingStates.has(requestState) && (
        <>
          <LoadingSkeleton variant="rounded" height="38px" className={styles.loadingSkeleton} />
        </>
      )}
      {requestState === RequestState.ERROR && (
        <ErrorComponent
          className={utilitiesStyles.NoBorder}
          testid={`${productName}-usage-loading-error`}
          text="Something went wrong"
        />
      )}
      {requestState === RequestState.IDLE && (
        <p className={styles.moneyDisplayText} data-testid="number-display">
          {spotlightedValue()}
        </p>
      )}
      <p className={styles.subtitle}>{subtitle}</p>
    </div>
  )
}
