import {Link} from '@primer/react'

import type {BudgetThresholdsSummary} from '../../types/budgets'
import {deriveSegments} from '../../utils/derive-budget-segments'
import InfoIconOverlay from '../usage/InfoIconOverlay'

import styles from './MultiUserBudgetOverview.module.css'

interface Props {
  consumedCopilotLicenses: number
  budgetThresholdsSummary?: BudgetThresholdsSummary
  analyticsPath: string
  licensingPath: string
}

export default function MultiUserBudgetOverview({
  consumedCopilotLicenses,
  budgetThresholdsSummary,
  analyticsPath,
  licensingPath,
}: Props) {
  const licenses = consumedCopilotLicenses ?? 0
  const totalUsers = licenses

  const segments = budgetThresholdsSummary ? deriveSegments(licenses, budgetThresholdsSummary) : null

  const noUsagePct = segments && totalUsers > 0 ? (segments.noUsage / totalUsers) * 100 : 0
  const belowPct = segments && totalUsers > 0 ? (segments.belowThreshold / totalUsers) * 100 : 0
  const nearPct = segments && totalUsers > 0 ? (segments.nearLimit / totalUsers) * 100 : 0
  const atOrAbovePct = segments && totalUsers > 0 ? (segments.atOrAboveLimit / totalUsers) * 100 : 0

  return (
    <div className={styles.container} data-testid="multi-user-budget-overview">
      <div className={styles.header}>
        <div className={styles.headerLeft}>
          <span className={styles.headerLabel}>Usage</span>
          <InfoIconOverlay
            infoLabel="Usage information"
            overlayTitle="Usage"
            overlayText={[
              'Only users who have used premium requests this month are shown here. For a complete list of all licensed users, go to the licensing page.',
            ]}
            link={licensingPath}
            linkText="Learn more about tracking user level budgets"
          />
        </div>
        <Link href={analyticsPath}>View analytics</Link>
      </div>

      <div className={styles.licensedUsers}>
        {licenses.toLocaleString()} licensed {licenses === 1 ? 'user' : 'users'}
      </div>

      {segments ? (
        <>
          <div className={styles.progressBar} role="img" aria-label="Budget usage distribution">
            {belowPct > 0 && (
              <div
                className={`${styles.progressSegment} ${styles.segmentBelowThreshold}`}
                style={{width: `${belowPct}%`}}
                data-testid="segment-below-threshold"
              />
            )}
            {nearPct > 0 && (
              <div
                className={`${styles.progressSegment} ${styles.segmentNearLimit}`}
                style={{width: `${nearPct}%`}}
                data-testid="segment-near-limit"
              />
            )}
            {atOrAbovePct > 0 && (
              <div
                className={`${styles.progressSegment} ${styles.segmentAtOrAboveLimit}`}
                style={{width: `${atOrAbovePct}%`}}
                data-testid="segment-at-or-above-limit"
              />
            )}
            {noUsagePct > 0 && (
              <div
                className={`${styles.progressSegment} ${styles.segmentNoUsage}`}
                style={{width: `${noUsagePct}%`}}
                data-testid="segment-no-usage"
              />
            )}
          </div>

          <div className={styles.legend}>
            <span className={styles.legendItem}>
              <span className={`${styles.legendDot} ${styles.dotBelowThreshold}`} />
              <span className={styles.legendText}>{'< 75% budget used'}</span> {segments.belowThreshold}
            </span>
            <span className={styles.legendItem}>
              <span className={`${styles.legendDot} ${styles.dotNearLimit}`} />
              <span className={styles.legendText}>Near limit</span> {segments.nearLimit}
            </span>
            <span className={styles.legendItem}>
              <span className={`${styles.legendDot} ${styles.dotAtOrAboveLimit}`} />
              <span className={styles.legendText}>At or above limit</span> {segments.atOrAboveLimit}
            </span>
          </div>
        </>
      ) : null}
    </div>
  )
}
