import {verifiedFetchJSON} from '@github-ui/verified-fetch'

export interface UpdateIncludedUsageNotificationRequest {
  value: string
  enterpriseSlug?: string
  organizationId?: string
}

export interface UpdateIncludedUsageNotificationResponse {
  success: boolean
  value: string
}

export interface UpdateIncludedUsageNotificationError {
  error: string
}

export const updateIncludedUsageNotification = async ({
  value,
  enterpriseSlug,
  organizationId,
}: UpdateIncludedUsageNotificationRequest): Promise<
  UpdateIncludedUsageNotificationResponse | UpdateIncludedUsageNotificationError
> => {
  // Determine the correct endpoint based on context
  let url: string
  if (enterpriseSlug) {
    url = `/enterprises/${enterpriseSlug}/billing/included_usage_notification`
  } else if (organizationId) {
    url = `/organizations/${organizationId}/settings/billing/included_usage_notification`
  } else {
    url = '/settings/billing/included_usage_notification'
  }

  try {
    const response = await verifiedFetchJSON(url, {
      method: 'PATCH',
      body: {value},
    })

    const data = await response.json()

    if (!response.ok) {
      return {error: data.error || 'Unable to update notification setting'}
    }

    return data as UpdateIncludedUsageNotificationResponse
  } catch {
    // Handle network errors or authentication redirects
    return {error: 'Unable to update notification setting. Please try again.'}
  }
}
