import type {QueryBuilderElement} from '@github-ui/query-builder-element'
import {
  FetchDataEvent,
  FilterItem,
  type FilterProvider,
  type QueryEvent,
} from '@github-ui/query-builder-element/query-builder-api'
import {hasMatch, score} from 'fzy.js'
import type {Environment} from 'react-relay'
import {fetchQuery, graphql} from 'react-relay'

import {TOP_USER_COUNT} from '../../constants/search-filters'
import type {
  billingOrganizationUserFilterProviderQuery,
  billingOrganizationUserFilterProviderQuery$data,
} from './__generated__/billingOrganizationUserFilterProviderQuery.graphql'

// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-queries
const OrganizationUsersQuery = graphql`
  query billingOrganizationUserFilterProviderQuery($slug: String!, $count: Int!, $phrase: String) {
    organization(login: $slug) {
      membersWithRole(first: $count, phrase: $phrase) {
        edges {
          node {
            login
            name
            avatarUrl
          }
        }
      }
    }
  }
`

type UserData = {
  login: string
  name: string | null | undefined
  avatarUrl: string
}

export class BillingOrganizationUserFilterProvider extends EventTarget implements FilterProvider {
  type = 'filter' as const
  name: string
  slug: string
  priority: number
  singularItemName: string
  value: string
  relayEnvironment: Environment

  topUserCache: UserData[] | undefined = undefined

  constructor(
    queryBuilder: QueryBuilderElement,
    {
      name,
      slug,
      value,
      priority,
      relayEnvironment,
    }: {
      name: string
      slug: string
      value: string
      priority: number
      relayEnvironment: Environment
    },
  ) {
    super()

    this.name = name
    this.slug = slug
    this.singularItemName = name
    this.value = value
    this.priority = priority
    this.relayEnvironment = relayEnvironment

    queryBuilder.addEventListener('query', this)
    queryBuilder.attachProvider(this)
  }

  async handleEvent(event: QueryEvent) {
    const lastElement = event.parsedQuery.at(-1)!

    if (
      (lastElement.value !== '' || this.priority <= 5) &&
      lastElement?.type !== 'filter' &&
      !event.parsedQuery.some(e => e.type === 'filter' && e.filter === this.value) &&
      (hasMatch(lastElement?.value, this.name) || hasMatch(lastElement?.value, this.value))
    ) {
      this.dispatchEvent(new Event('show'))
    }

    if (lastElement?.type !== this.type || lastElement.filter !== this.value) return

    if (!this.topUserCache) {
      // Immediately set this to avoid multiple requests
      this.topUserCache = []
      const fetchPromise = this.fetchTopUsers(event)
      this.dispatchEvent(new FetchDataEvent(fetchPromise))
    } else {
      // An organization might have a large number of users that might not be included in the initial fetch.
      // In this case, we check if the user is searching for something outside the cache and re-query if so.
      const searchedUserExistsInCache = this.topUserCache.some(user => hasMatch(lastElement.value, user.login))
      if (!searchedUserExistsInCache) {
        const fetchPromise = this.fetchTopUsers(event)
        this.dispatchEvent(new FetchDataEvent(fetchPromise))
        return
      }

      // Only show users that match the current query
      const matchingUsers = this.topUserCache.filter(
        user => hasMatch(lastElement.value, user.login) || (user.name && hasMatch(lastElement.value, user.name)),
      )

      for (const user of matchingUsers) {
        this.emitSuggestion(user.login, user.name ?? '', user.avatarUrl, lastElement.value)
      }
    }
  }

  async fetchTopUsers(event: QueryEvent) {
    let topUsers: billingOrganizationUserFilterProviderQuery$data | undefined
    const currentQueryValue = event.parsedQuery.at(-1)?.value

    try {
      topUsers = await fetchQuery<billingOrganizationUserFilterProviderQuery>(
        this.relayEnvironment,
        OrganizationUsersQuery,
        {
          slug: this.slug,
          phrase: currentQueryValue,
          count: TOP_USER_COUNT,
        },
      ).toPromise()
    } catch {
      // If we have an error, we don't want to cache the results, so we can retry later.
      this.topUserCache = undefined
      return
    }

    const query = event.parsedQuery.at(-1)!.value

    if (topUsers?.organization?.membersWithRole.edges) {
      for (const userEdge of topUsers.organization.membersWithRole.edges) {
        const userLogin = userEdge?.node?.login
        const userAvatarUrl = userEdge?.node?.avatarUrl
        const userName = userEdge?.node?.name

        // Add the user to the cache if it has a login and does not already exist
        const userExistsInCache = this.topUserCache?.some(cachedUser => cachedUser.login === userLogin)
        if (userLogin && userAvatarUrl && !userExistsInCache) {
          this.topUserCache!.push({login: userLogin, name: userName, avatarUrl: userAvatarUrl})
          this.emitSuggestion(userLogin, userName ?? '', userAvatarUrl, query)
        }
      }
    }
  }

  emitSuggestion(login: string, name: string, avatarUrl: string | undefined, query: string) {
    let priority = 3

    if (query) {
      // Weight the score more heavily by login, then influence by name
      const loginWeighting = 0.75
      priority -= score(query, login) * loginWeighting
      priority -= score(query, name) * (1 - loginWeighting)
    }

    this.dispatchEvent(
      new FilterItem({
        filter: this.value,
        value: login,
        description: name,
        inlineDescription: true,
        priority,
        icon: 'person',
        avatar: avatarUrl
          ? {
              url: avatarUrl,
              type: 'user',
            }
          : undefined,
      }),
    )
  }
}
