import {RadioGroup, Radio, Spinner, Heading, FormControl, Checkbox, Label, Link} from '@primer/react'
import {useQueryLoader, fetchQuery, readInlineData, useRelayEnvironment} from 'react-relay'
import {Suspense, useEffect, useState, useTransition, use} from 'react'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {PageContext} from '../../App'

import {
  BUDGET_SCOPE_CUSTOMER,
  BUDGET_SCOPE_COST_CENTER,
  BUDGET_SCOPE_MULTI_USER_CUSTOMER,
  BUDGET_SCOPE_ORGANIZATION,
  BUDGET_SCOPE_REPOSITORY,
  BUDGET_SCOPE_USER,
  HighWatermarkProducts,
  HighWatermarkSkus,
} from '../../constants'
import {SKUs, Bundles} from '../../constants/products'

import {CostCenterPicker} from '../pickers/CostCenterPicker'
import {PaginatedCostCenterPicker} from '../pickers/PaginatedCostCenterPicker'
import {OrgRepositoryPicker, OrgRepositoryPickerRecentQuery} from '../pickers/OrgRepositoryPicker'
import {UserRepositoryPicker, UserRepositoryPickerRecentQuery} from '../pickers/UserRepositoryPicker'

import type {OrgRepositoryPickerRecentQuery as OrgRepositoryPickerQueryType} from '../pickers/__generated__/OrgRepositoryPickerRecentQuery.graphql'
import type {UserRepositoryPickerRecentQuery as UserRepositoryPickerQueryType} from '../pickers/__generated__/UserRepositoryPickerRecentQuery.graphql'

import type {BudgetPicker} from '../../types/budgets'
import type {User} from '../pickers/UserPicker'
import {UserPicker, UserPickerSearchQuery, UserPickerUserFragment} from '../pickers/UserPicker'
import type {UserPickerSearchQuery as UserPickerSearchQueryType} from '../pickers/__generated__/UserPickerSearchQuery.graphql'
import type {UserPickerUserFragment$key} from '../pickers/__generated__/UserPickerUserFragment.graphql'
import {OrganizationPickerParentGraphqlQuery, PaginatedOrganizationPicker} from '../pickers/PaginatedOrganizationPicker'
import type {PaginatedOrganizationPickerGraphqlQuery} from '../pickers/__generated__/PaginatedOrganizationPickerGraphqlQuery.graphql'

import styles from './BudgetScopeSelector.module.css'
import type {PaginatedRepositoryPickerGraphqlQuery} from '../pickers/__generated__/PaginatedRepositoryPickerGraphqlQuery.graphql'
import {
  PaginatedRepositoryPicker,
  PaginatedRepositoryPickerParentGraphqlQuery,
} from '../pickers/PaginatedRepositoryPicker'

interface Props {
  budgetScope: string
  setBudgetScope: (budgetScope: string) => void
  setBudgetScopeId: (budgetScopeIds: string[]) => void
  budgetScopeIds: string[]
  slug: string
  disablePicker?: BudgetPicker[]
  budgetProduct: string
  excludeCostCenters?: boolean
  setExcludeCostCenters?: (exclude: boolean) => void
  initialUserId?: string
}

export function BudgetScopeSelector({
  budgetScope,
  setBudgetScope,
  setBudgetScopeId,
  budgetScopeIds,
  slug,
  disablePicker,
  budgetProduct,
  excludeCostCenters = false,
  setExcludeCostCenters,
  initialUserId,
}: Props) {
  const {isOrganizationRoute, isEnterpriseRoute, isUserRoute} = use(PageContext)
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const isExcludeCostCentersEnabled = useFeatureFlag('billing_enterprise_budget_option_to_exclude_cost_centers')
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const isUserLevelBudgetsEnabled = useFeatureFlag('billing_user_level_budgets_manage')
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const isPaginatedCostCentersEnabled = useFeatureFlag('billing_cost_centers_ui_pagination_enabled')
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const disableOrgAdminPagination = useFeatureFlag('billing_cost_centers_disable_org_admin_pagination')
  const billingCostCentersUIPagination = isPaginatedCostCentersEnabled && !disableOrgAdminPagination
  const showExcludeCostCentersOption = isEnterpriseRoute && isExcludeCostCentersEnabled
  const isPremiumRequestsBundle = budgetProduct === Bundles.PremiumRequests
  const showUserLevelBudgetOption = isEnterpriseRoute && isUserLevelBudgetsEnabled && isPremiumRequestsBundle

  const environment = useRelayEnvironment()
  const [initialUser, setInitialUser] = useState<User[]>([])

  useEffect(() => {
    if (!initialUserId) {
      return
    }

    // initialUserId is a login/username string (from URL params), so we search
    // by phrase and match on login rather than using node ID lookup.
    const subscription = fetchQuery<UserPickerSearchQueryType>(environment, UserPickerSearchQuery, {
      slug,
      query: initialUserId,
    }).subscribe({
      next: data => {
        const nodes = (data.enterprise?.organizationsMembers?.nodes || []).flatMap(node =>
          // eslint-disable-next-line no-restricted-syntax
          node ? [readInlineData<UserPickerUserFragment$key>(UserPickerUserFragment, node)] : [],
        )
        const matched = nodes.filter(u => u.login.toLowerCase() === initialUserId.toLowerCase())
        const resolvedUser = matched[0]
        if (resolvedUser) {
          setInitialUser(matched)
          // Update the scope ID to the resolved user's database ID so the API accepts it
          setBudgetScopeId([String(resolvedUser.databaseId ?? resolvedUser.id)])
        } else {
          setInitialUser([{id: initialUserId, login: initialUserId, viewOnly: true} as User])
          setBudgetScopeId([])
        }
      },
      error: () => {
        setInitialUser([{id: initialUserId, login: initialUserId, viewOnly: true} as User])
        setBudgetScopeId([])
      },
    })

    return () => {
      subscription.unsubscribe()
    }
  }, [environment, initialUserId, slug, setBudgetScopeId])

  const excludeCostCentersValue = excludeCostCenters
  const handleExcludeCostCentersChange = (checked: boolean) => {
    setExcludeCostCenters?.(checked)
  }

  const initialOrganizationScopeId = budgetScopeIds && budgetScope === BUDGET_SCOPE_ORGANIZATION ? budgetScopeIds : []
  const initialRepositoryScopeId = budgetScopeIds && budgetScope === BUDGET_SCOPE_REPOSITORY ? budgetScopeIds : []

  const [paginatedOrganizationsRef, loadPaginatedOrganizations, disposePaginatedOrganizationsRef] =
    useQueryLoader<PaginatedOrganizationPickerGraphqlQuery>(OrganizationPickerParentGraphqlQuery)

  const [paginatedRepositoriesRef, loadPaginatedRepositories, disposePaginatedRepositoriesRef] =
    useQueryLoader<PaginatedRepositoryPickerGraphqlQuery>(PaginatedRepositoryPickerParentGraphqlQuery)

  const [orgRepositoriesRef, loadOrgRepositories, disposeOrgRepositoriesRef] =
    useQueryLoader<OrgRepositoryPickerQueryType>(OrgRepositoryPickerRecentQuery)

  const [userRepositoriesRef, loadUserRepositories, disposeUserRepositoriesRef] =
    useQueryLoader<UserRepositoryPickerQueryType>(UserRepositoryPickerRecentQuery)

  const [, startTransition] = useTransition()
  const [usersRef, loadUsers, disposeUsersRef] = useQueryLoader<UserPickerSearchQueryType>(UserPickerSearchQuery)

  const isProductHighWaterMark = () => {
    return (
      Object.values(HighWatermarkProducts).includes(budgetProduct as HighWatermarkProducts) ||
      Object.values(HighWatermarkSkus).includes(budgetProduct as HighWatermarkSkus)
    )
  }

  const orgViewOfHighWatermark = isProductHighWaterMark() && isOrganizationRoute

  useEffect(() => {
    if (isEnterpriseRoute) {
      loadPaginatedOrganizations({slug}, {fetchPolicy: 'store-or-network'})
      if (showUserLevelBudgetOption) {
        startTransition(() => {
          loadUsers({slug}, {fetchPolicy: 'store-or-network'})
        })
      }
    }
    if (!disablePicker?.includes('repo')) {
      if (isOrganizationRoute) {
        loadOrgRepositories({slug}, {fetchPolicy: 'store-or-network'})
      } else if (isUserRoute) {
        loadUserRepositories({}, {fetchPolicy: 'store-or-network'})
      } else {
        loadPaginatedRepositories({slug}, {fetchPolicy: 'store-or-network'})
      }
    }
    if (orgViewOfHighWatermark) {
      setBudgetScope(BUDGET_SCOPE_CUSTOMER)
    }

    return () => {
      disposePaginatedOrganizationsRef()
      disposeOrgRepositoriesRef()
      disposeUserRepositoriesRef()
      disposePaginatedRepositoriesRef()
      disposeUsersRef()
    }
  }, [
    slug,
    budgetScopeIds,
    budgetScope,
    loadPaginatedOrganizations,
    disposePaginatedOrganizationsRef,
    disablePicker,
    isOrganizationRoute,
    loadOrgRepositories,
    disposeOrgRepositoriesRef,
    orgViewOfHighWatermark,
    setBudgetScope,
    loadUserRepositories,
    disposeUserRepositoriesRef,
    isEnterpriseRoute,
    isUserRoute,
    loadPaginatedRepositories,
    disposePaginatedRepositoriesRef,
    loadUsers,
    disposeUsersRef,
    showUserLevelBudgetOption,
  ])

  const handleBudgetScopeChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setBudgetScope(event.target.value)
    const scopeId =
      event.target.value === BUDGET_SCOPE_CUSTOMER || event.target.value === BUDGET_SCOPE_MULTI_USER_CUSTOMER
        ? ['1']
        : []
    setBudgetScopeId(scopeId)
  }

  const isCopilotProduct = (product: string) => {
    return (
      product === HighWatermarkProducts.copilot ||
      product === HighWatermarkSkus.copilot_standalone ||
      product === HighWatermarkSkus.copilot_for_business ||
      product === HighWatermarkSkus.copilot_enterprise ||
      product === SKUs.CopilotPremiumRequestSku
    )
  }

  const setAllSelectedCostCenters = (selectedIds: string[]) => {
    if (isPaginatedCostCentersEnabled) {
      setBudgetScopeId(selectedIds[0] ? [selectedIds[0]] : [])
    } else if (selectedIds[0]) {
      setBudgetScopeId([selectedIds[0]])
    }
  }

  const visibleBudgetScopes = [
    !disablePicker?.includes('enterprise') && BUDGET_SCOPE_CUSTOMER,
    !disablePicker?.includes('org') && BUDGET_SCOPE_ORGANIZATION,
    isUserRoute && BUDGET_SCOPE_CUSTOMER,
    !disablePicker?.includes('repo') &&
      !orgViewOfHighWatermark &&
      !(isUserRoute && isCopilotProduct(budgetProduct)) &&
      BUDGET_SCOPE_REPOSITORY,
    !disablePicker?.includes('cost_center') && BUDGET_SCOPE_COST_CENTER,
  ].filter(Boolean)

  const isSingleScope = visibleBudgetScopes.length === 1

  const getScopeLabel = (scope: string | undefined): string => {
    switch (scope) {
      case BUDGET_SCOPE_CUSTOMER:
        // Handle CUSTOMER scope differently based on the route
        if (isUserRoute) {
          return 'Account'
        } else if (isOrganizationRoute) {
          return 'Organization'
        } else {
          return 'Enterprise'
        }
      case BUDGET_SCOPE_ORGANIZATION:
        return 'Organization'
      case BUDGET_SCOPE_REPOSITORY:
        return 'Repository'
      case BUDGET_SCOPE_COST_CENTER:
        return 'Cost center'
      case BUDGET_SCOPE_MULTI_USER_CUSTOMER:
        return 'Users'
      default:
        return 'Account'
    }
  }

  const getScopeDescription = (scope: string | undefined): string => {
    switch (scope) {
      case BUDGET_SCOPE_CUSTOMER:
        // Handle CUSTOMER scope differently based on the route
        if (isUserRoute) {
          if (isSingleScope) {
            return 'Scoped budgets track all spending for your account'
          } else {
            return 'Scoped budgets track spending for all repositories owned by your account'
          }
        } else if (isOrganizationRoute) {
          return 'Scoped budgets track spending for all repositories in the organization'
        } else {
          return 'Scoped budgets track spending for all organizations, repositories and cost centers in the enterprise'
        }
      case BUDGET_SCOPE_ORGANIZATION:
        return 'Scoped budgets track spending for all repositories in the organization'
      case BUDGET_SCOPE_REPOSITORY:
        return 'Scoped budgets track spending for a single repository'
      case BUDGET_SCOPE_COST_CENTER:
        return 'Scoped budgets track spending for a single cost center'
      case BUDGET_SCOPE_MULTI_USER_CUSTOMER:
        return 'Each user in your enterprise gets their own individual budget.'
      case BUDGET_SCOPE_USER:
        return 'Scoped budget for an individual user.'
      default:
        return 'Scoped budgets track spending for all repositories owned by your account'
    }
  }

  if (isSingleScope) {
    const singleScope = visibleBudgetScopes[0] as string
    setBudgetScope(BUDGET_SCOPE_CUSTOMER)

    return (
      <div>
        <Heading as="h2" id="budget-scope-choices" className={styles.Heading}>
          Budget scope
        </Heading>
        <div className={styles.BudgetSubTitleBox}>
          <span>Select the scope of spending for this budget.</span>
        </div>
        <div className="Box">
          <div className="Box-row">
            <FormControl>
              <FormControl.Label>{getScopeLabel(singleScope)}</FormControl.Label>
              <FormControl.Caption style={{fontSize: 'var(--base-size-14)'}}>
                {getScopeDescription(singleScope)}
              </FormControl.Caption>
            </FormControl>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div>
      <Heading as="h2" id="budget-scope-choices" className={styles.Heading}>
        Budget scope
      </Heading>
      <div className={styles.BudgetSubTitleBox}>
        <span>Select the scope of spending for this budget.</span>
      </div>
      <RadioGroup aria-labelledby="budget-scope-choices" name="budget-scope-choices">
        <div className="Box">
          {!disablePicker?.includes('enterprise') && (
            <div className="Box-row">
              <FormControl>
                <Radio
                  checked={budgetScope === BUDGET_SCOPE_CUSTOMER}
                  value={BUDGET_SCOPE_CUSTOMER}
                  onChange={e => {
                    handleBudgetScopeChange(e)
                  }}
                />
                <FormControl.Label>{getScopeLabel(BUDGET_SCOPE_CUSTOMER)}</FormControl.Label>
                <FormControl.Caption className={styles.Caption}>
                  {getScopeDescription(BUDGET_SCOPE_CUSTOMER)}
                </FormControl.Caption>
              </FormControl>
              {showExcludeCostCentersOption && budgetScope === BUDGET_SCOPE_CUSTOMER && (
                <FormControl style={{marginTop: 'var(--base-size-8)', marginLeft: 'var(--base-size-24)'}}>
                  <Checkbox
                    checked={excludeCostCentersValue}
                    onChange={e => handleExcludeCostCentersChange(e.target.checked)}
                  />
                  <FormControl.Label>
                    Exclude cost center usage from this budget <Label variant="done">Preview</Label>
                  </FormControl.Label>
                  <FormControl.Caption style={{fontSize: 'var(--base-size-12)'}}>
                    If selected, cost center usage will <strong>not</strong> be limited by this budget.{' '}
                    <Link href="https://gh.io/exclude-cost-center" inline target="_blank" rel="noopener noreferrer">
                      Learn more.
                    </Link>
                  </FormControl.Caption>
                </FormControl>
              )}
            </div>
          )}
          {!disablePicker?.includes('org') && (
            <div className="Box-row">
              <FormControl
                style={{marginBottom: budgetScope === BUDGET_SCOPE_ORGANIZATION ? 'var(--base-size-16)' : '0px'}}
                disabled={orgViewOfHighWatermark}
              >
                <Radio
                  value={isOrganizationRoute ? BUDGET_SCOPE_CUSTOMER : BUDGET_SCOPE_ORGANIZATION}
                  checked={
                    orgViewOfHighWatermark ||
                    budgetScope === BUDGET_SCOPE_ORGANIZATION ||
                    (isOrganizationRoute && budgetScope === BUDGET_SCOPE_CUSTOMER)
                  }
                  onChange={e => {
                    handleBudgetScopeChange(e)
                  }}
                />
                <FormControl.Label>{getScopeLabel(BUDGET_SCOPE_ORGANIZATION)}</FormControl.Label>
                <FormControl.Caption className={styles.Caption}>
                  {getScopeDescription(BUDGET_SCOPE_ORGANIZATION)}
                </FormControl.Caption>
              </FormControl>
              {!isOrganizationRoute && budgetScope === BUDGET_SCOPE_ORGANIZATION && (
                <Suspense fallback={<Spinner size="small" />}>
                  {paginatedOrganizationsRef && (
                    <PaginatedOrganizationPicker
                      preloadedOrganizationsRef={paginatedOrganizationsRef}
                      setSelectedItems={setBudgetScopeId}
                      initialSelectedItemIds={initialOrganizationScopeId}
                      selectionVariant="single"
                    />
                  )}
                </Suspense>
              )}
            </div>
          )}
          {!disablePicker?.includes('repo') && (
            <div className="Box-row">
              <FormControl
                style={{marginBottom: budgetScope === BUDGET_SCOPE_REPOSITORY ? 'var(--base-size-16)' : '0px'}}
              >
                <Radio
                  checked={budgetScope === BUDGET_SCOPE_REPOSITORY}
                  value={BUDGET_SCOPE_REPOSITORY}
                  onChange={e => {
                    handleBudgetScopeChange(e)
                  }}
                />
                <FormControl.Label>{getScopeLabel(BUDGET_SCOPE_REPOSITORY)}</FormControl.Label>
                <FormControl.Caption className={styles.Caption}>
                  {getScopeDescription(BUDGET_SCOPE_REPOSITORY)}
                </FormControl.Caption>
              </FormControl>
              {budgetScope === BUDGET_SCOPE_REPOSITORY && (
                <>
                  {isOrganizationRoute && orgRepositoriesRef && (
                    <Suspense fallback={<Spinner size="small" />}>
                      <OrgRepositoryPicker
                        preloadedRepositoriesRef={orgRepositoriesRef}
                        slug={slug}
                        setSelectedItems={setBudgetScopeId}
                        initialSelectedItemIds={initialRepositoryScopeId}
                        selectionVariant="single"
                      />
                    </Suspense>
                  )}
                  {isUserRoute && userRepositoriesRef && (
                    <Suspense fallback={<Spinner size="small" />}>
                      <UserRepositoryPicker
                        preloadedRepositoriesRef={userRepositoriesRef}
                        setSelectedItems={setBudgetScopeId}
                        initialSelectedItemIds={initialRepositoryScopeId}
                        selectionVariant="single"
                      />
                    </Suspense>
                  )}
                  {paginatedRepositoriesRef && isEnterpriseRoute && (
                    <Suspense fallback={<Spinner size="small" />}>
                      <PaginatedRepositoryPicker
                        preloadedRepositoriesRef={paginatedRepositoriesRef}
                        slug={slug}
                        setSelectedItems={setBudgetScopeId}
                        initialSelectedItemIds={initialRepositoryScopeId}
                        selectionVariant="single"
                      />
                    </Suspense>
                  )}
                </>
              )}
            </div>
          )}
          {!disablePicker?.includes('cost_center') && (
            <div className="Box-row">
              <FormControl
                style={{marginBottom: budgetScope === BUDGET_SCOPE_COST_CENTER ? 'var(--base-size-16)' : '0px'}}
              >
                <Radio
                  checked={budgetScope === BUDGET_SCOPE_COST_CENTER}
                  value={BUDGET_SCOPE_COST_CENTER}
                  onChange={e => {
                    handleBudgetScopeChange(e)
                  }}
                />
                <FormControl.Label>{getScopeLabel(BUDGET_SCOPE_COST_CENTER)}</FormControl.Label>
                <FormControl.Caption className={styles.Caption}>
                  {getScopeDescription(BUDGET_SCOPE_COST_CENTER)}
                </FormControl.Caption>
              </FormControl>
              {budgetScope === BUDGET_SCOPE_COST_CENTER && (
                <Suspense fallback={<Spinner size="small" />}>
                  {billingCostCentersUIPagination ? (
                    <PaginatedCostCenterPicker
                      setAllSelectedCostCenters={setAllSelectedCostCenters}
                      selectionVariant="single"
                    />
                  ) : (
                    <CostCenterPicker
                      initialSelectedItems={[]}
                      setAllSelectedCostCenters={setAllSelectedCostCenters}
                      selectionVariant="single"
                    />
                  )}
                </Suspense>
              )}
            </div>
          )}
          {showUserLevelBudgetOption && (
            <div className="Box-row">
              <FormControl>
                <Radio
                  checked={budgetScope === BUDGET_SCOPE_MULTI_USER_CUSTOMER || budgetScope === BUDGET_SCOPE_USER}
                  value={BUDGET_SCOPE_MULTI_USER_CUSTOMER}
                  onChange={e => {
                    handleBudgetScopeChange(e)
                  }}
                />
                <FormControl.Label>
                  {getScopeLabel(BUDGET_SCOPE_MULTI_USER_CUSTOMER)} <Label variant="done">New</Label>
                </FormControl.Label>
                <FormControl.Caption className={styles.Caption}>
                  {getScopeDescription(
                    budgetScope === BUDGET_SCOPE_USER ? BUDGET_SCOPE_USER : BUDGET_SCOPE_MULTI_USER_CUSTOMER,
                  )}
                </FormControl.Caption>
              </FormControl>
              <div style={{marginTop: 'var(--base-size-8)', marginLeft: 'var(--base-size-24)'}}>
                <Suspense fallback={<Spinner size="small" />}>
                  {usersRef && (
                    <UserPicker
                      slug={slug}
                      onSelectionChange={(users: User[]) => {
                        const selectedUser = users.find(u => !!u.id)
                        if (selectedUser) {
                          setBudgetScope(BUDGET_SCOPE_USER)
                          setBudgetScopeId([String(selectedUser.databaseId ?? selectedUser.id)])
                        } else {
                          setBudgetScopeId([])
                        }
                      }}
                      initialUsers={initialUser}
                      preloadedData={{
                        type: 'roleBasedMembers',
                        data: usersRef,
                      }}
                      itemType="users"
                      selectionVariant="single"
                    />
                  )}
                </Suspense>
              </div>
            </div>
          )}
          {isUserRoute && (
            <div className="Box-row">
              <FormControl>
                <Radio
                  checked={budgetScope === BUDGET_SCOPE_CUSTOMER}
                  value={BUDGET_SCOPE_CUSTOMER}
                  onChange={e => {
                    handleBudgetScopeChange(e)
                  }}
                />
                <FormControl.Label>{getScopeLabel(BUDGET_SCOPE_CUSTOMER)}</FormControl.Label>
                <FormControl.Caption className={styles.Caption}>
                  {getScopeDescription(BUDGET_SCOPE_CUSTOMER)}
                </FormControl.Caption>
              </FormControl>
            </div>
          )}
        </div>
      </RadioGroup>
    </div>
  )
}
