import {Button} from '@primer/react'

import styles from './BillingJobTableCell.module.css'

interface Props {
  text: string
  style?: React.CSSProperties
  onClick?: () => void
}

export type BillingJobTableCellData =
  | string
  | {
      text: string
      style?: React.CSSProperties
      onClick?: () => void
    }

// eslint-disable-next-line @eslint-react/no-unstable-default-props
export default function BillingJobTableCell({text, style = {}, onClick}: Props) {
  // eslint-disable-next-line react-hooks/immutability
  if (!style.width && !style.flex) style.flex = 1

  return (
    <div className={styles.cell} style={style}>
      {onClick ? <Button onClick={onClick}>{text}</Button> : text}
    </div>
  )
}
