import {ChevronLeftIcon, ChevronRightIcon} from '@primer/octicons-react'
import {Button, Pagination} from '@primer/react'
import {Box} from '@primer/styled-react'
import {BUDGETS_PAGE_SIZE} from '../../constants'

type Props = {
  currentPage: number
  onPageChange: (page: number) => void
  hasNextPage?: boolean
  hasPreviousPage?: boolean
  totalCount?: number
  pageSize?: number
}

export default function ServerSidePagination({
  currentPage,
  onPageChange,
  hasNextPage,
  hasPreviousPage,
  totalCount = 0,
  pageSize = BUDGETS_PAGE_SIZE,
}: Props) {
  // If we don't have explicit hasNext/hasPrev, try to determine from other props
  const shouldShowPrevious = hasPreviousPage ?? currentPage > 1
  const shouldShowNext = hasNextPage ?? true

  // When totalCount is greater than 0, use Primer's Pagination for numbered pages
  if (totalCount > 0) {
    const pageCount = Math.ceil(totalCount / pageSize)
    // Don't show pagination if only 1 page
    if (pageCount <= 1) {
      return null
    }
    const handlePageChange: Parameters<typeof Pagination>['0']['onPageChange'] = (e, page) => {
      e.preventDefault()
      onPageChange(page)
    }
    return <Pagination pageCount={pageCount} currentPage={currentPage} onPageChange={handlePageChange} />
  }

  // Fallback: prev/next only mode when totalCount is not available
  // Don't render if we're on page 1 and there's no next page
  if (currentPage === 1 && !shouldShowNext) {
    return null
  }

  const handlePreviousClick = () => {
    if (shouldShowPrevious) {
      onPageChange(currentPage - 1)
    }
  }

  const handleNextClick = () => {
    if (shouldShowNext) {
      onPageChange(currentPage + 1)
    }
  }

  return (
    <Box
      sx={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 3,
        py: 3,
      }}
    >
      <Button
        variant="invisible"
        leadingVisual={ChevronLeftIcon}
        onClick={handlePreviousClick}
        disabled={!shouldShowPrevious}
        aria-label="Previous page"
      >
        Previous
      </Button>

      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          minWidth: 32,
          height: 32,
          borderRadius: '6px',
          backgroundColor: 'accent.emphasis',
          color: 'fg.onEmphasis',
          fontSize: 1,
          fontWeight: '600',
        }}
      >
        {currentPage}
      </Box>

      <Button
        variant="invisible"
        trailingVisual={ChevronRightIcon}
        onClick={handleNextClick}
        disabled={!shouldShowNext}
        aria-label="Next page"
      >
        Next
      </Button>
    </Box>
  )
}
