import {useCallback, useState} from 'react'
// eslint-disable-next-line no-restricted-imports
import {useToastContext} from '@github-ui/toast/ToastContext'

import useRequest from '../use-request'

import {ERRORS} from '../../constants'
import {DISCOUNTS_ROUTE} from '../../routes'
import {filterbyEnabledProducts, getUpdatedDiscountAmounts} from '../../utils/discount'

import type {EnabledProduct} from '../../types/products'
import type {DiscountStatesByTargetType, DiscountState} from '../../types/discounts'

type LoadDiscountsParams = {
  enabledProducts: EnabledProduct[]
  filterIncludedUsage?: boolean
  month?: number
  year?: number
}

function useDiscounts({enabledProducts, filterIncludedUsage = false, month, year}: LoadDiscountsParams) {
  const [discountStates, setDiscountStates] = useState<DiscountState[]>([])
  const [enabledProductDiscountStates, setEnabledProductDiscountStates] = useState<DiscountState[]>([])
  const [enabledProductDiscountTargetAmounts, setEnabledProductDiscountTargetAmounts] =
    useState<DiscountStatesByTargetType>({})
  const [isLoadingDiscounts, setLoadingDiscounts] = useState(true)
  const [reloadKey, setReloadKey] = useState(0)
  const {addToast} = useToastContext()

  // getMonth() is 0 based, but we need to pass in a value between 1-12
  const targetMonth = month ?? new Date().getUTCMonth() + 1
  const targetYear = year ?? new Date().getUTCFullYear()

  useRequest({
    route: DISCOUNTS_ROUTE,
    reqParams: {
      month: targetMonth.toString(),
      year: targetYear.toString(),
      reloadKey: reloadKey.toString(),
      ...(filterIncludedUsage && {
        filter_included_usage: filterIncludedUsage.toString(),
      }),
    },
    onStart: () => {
      setLoadingDiscounts(true)
      setDiscountStates([])
      setEnabledProductDiscountStates([])
      setEnabledProductDiscountTargetAmounts({})
    },
    onSuccess: response => {
      const allDiscounts = response.data.discounts
      const enabledDiscounts = allDiscounts.filter(filterbyEnabledProducts(enabledProducts))
      const targetAmounts = getUpdatedDiscountAmounts(enabledDiscounts)
      setDiscountStates(allDiscounts)
      setEnabledProductDiscountStates(enabledDiscounts)
      setEnabledProductDiscountTargetAmounts(targetAmounts)
      setLoadingDiscounts(false)
    },
    onError: () => {
      // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
      addToast({
        type: 'error',
        message: ERRORS.QUERY_DISCOUNTS_ERROR,
      })
      setLoadingDiscounts(false)
    },
  })

  const refetch = useCallback(() => {
    setReloadKey(k => k + 1)
  }, [])

  return {
    discountStates,
    enabledProductDiscountStates,
    enabledProductDiscountTargetAmounts,
    isLoadingDiscounts,
    refetch,
  }
}

export default useDiscounts
