interface Props {
  children: React.ReactNode
  'data-hpc'?: boolean
}

export default function Layout(props: Props) {
  const {children, 'data-hpc': dataHpc} = props

  return (
    <div data-hpc={dataHpc ? true : undefined}>
      {/* Screen reader live region for announcements */}
      <div id="js-global-screen-reader-notice" className="sr-only" aria-live="polite" aria-atomic="true" />
      {children}
    </div>
  )
}
