import {OrganizationIcon, RepoIcon, PersonIcon} from '@primer/octicons-react'
import {Pagination} from '@primer/react'
import {Box, Text, Label} from '@primer/styled-react'
import Pluralize from 'pluralize'
import {use, useState, useEffect} from 'react'
import {useNavigate} from '@github-ui/use-navigate'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'

import {ResourceType} from '../../enums/cost-centers'
import {PageContext, ReloadContext} from '../../App'
import {CostCenterTabs} from '../../routes/CostCentersPage'
import {COST_CENTERS_ROUTE} from '../../routes'
import useRoute from '../../hooks/use-route'
import {boxStyle, tableHeaderStyle, tableContainerStyle, tableRowStyle} from '../../utils/style'

import CostCenterActionMenu from './CostCenterActionMenu'
import ServerSidePagination from '../common/ServerSidePagination'

import styles from './CostCentersTable.module.css'

import type {CostCenter} from '../../types/cost-centers'

const tableDataCellStyleName = {
  p: 3,
  display: 'flex',
  flexDirection: 'column',
  width: ['100%', 'auto', 'auto'],
  justifyContent: 'space-between',
}

type Props = {
  costCenters: CostCenter[]
  selectedTab: CostCenterTabs
  hasUserScopedCostCenters: boolean
  billingAddCostCenterDescription: boolean
  currentPage?: number
  // Server-side pagination props (used when feature flag is enabled)
  hasNextPage?: boolean
  hasPreviousPage?: boolean
  totalCount?: number
}

export default function CostCentersTable({
  costCenters,
  selectedTab,
  hasUserScopedCostCenters: _hasUserScopedCostCenters,
  billingAddCostCenterDescription = false,
  currentPage = 1,
  hasNextPage,
  hasPreviousPage,
  totalCount,
}: Props) {
  const pageSize = 10
  const [pageNumber, setPageNumber] = useState(1)
  const [oldCurrentPage, setOldCurrentPage] = useState(1)
  const [currData, setCurrData] = useState<CostCenter[]>([])
  const [pagedData, setPagedData] = useState<CostCenter[]>([])
  const isStafftoolsRoute = use(PageContext).isStafftoolsRoute
  const {reloadKey} = use(ReloadContext)
  const navigate = useNavigate()
  const {path: costCentersBaseUrl} = useRoute(COST_CENTERS_ROUTE)
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const billingCostCentersUIPagination = useFeatureFlag('billing_cost_centers_ui_pagination_enabled')
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const disableOrgAdminPagination = useFeatureFlag('billing_cost_centers_disable_org_admin_pagination')
  const billingCostCentersUIChanges = billingCostCentersUIPagination && !disableOrgAdminPagination

  const tableRowStyleRowtoCol = billingAddCostCenterDescription
    ? {
        p: 0,
        flexDirection: ['column', 'row', 'row'],
        flexWrap: ['nowrap', 'wrap', 'wrap'],
        display: 'flex',
        alignItems: [null, 'center', 'center'],
        width: '100%',
      }
    : {
        p: 0,
        flexDirection: ['column', 'row', 'row'],
        flexWrap: ['nowrap', 'wrap', 'wrap'],
        display: 'flex',
        alignItems: [null, 'center', 'center'],
      }

  const onPageChange: Parameters<typeof Pagination>['0']['onPageChange'] = (e, page) => {
    e.preventDefault()
    if (billingCostCentersUIChanges) {
      // New URL-based navigation
      navigate(`${costCentersBaseUrl}?state=${selectedTab}&page=${page}`)
    } else {
      // Old onClick-based pagination
      setOldCurrentPage(page)
    }
  }

  // Handler for server-side pagination
  const onServerSidePageChange = (page: number) => {
    navigate(`${costCentersBaseUrl}?state=${selectedTab}&page=${page}`)
  }

  useEffect(() => {
    if (!billingCostCentersUIChanges) {
      // Only reset oldCurrentPage when using old pagination system
      setOldCurrentPage(1)
    }

    if (billingCostCentersUIChanges) {
      // For server-side pagination, use data as-is (already paginated by server)
      setCurrData(costCenters)
      setPagedData(costCenters)
    } else {
      // For client-side pagination, sort the data
      setCurrData(costCenters.sort((a, b) => a.name.localeCompare(b.name)))
    }
  }, [costCenters, billingCostCentersUIChanges])

  useEffect(() => {
    if (!billingCostCentersUIChanges) {
      // Only do client-side pagination when feature flag is off
      const updatePagedData = async () => {
        setPageNumber(Math.ceil(currData.length / (1.0 * pageSize)) || 1)
        setPagedData(currData.slice((oldCurrentPage - 1) * pageSize, oldCurrentPage * pageSize))
      }
      updatePagedData()
    }
  }, [currData, oldCurrentPage, billingCostCentersUIChanges, pageSize])

  useEffect(() => {
    // reload cost centers page when the reload key changes
    // this is to handle the useFeatureFlag issue where the FF shows as false on the first render
    // Only do full page reload when pagination is NOT enabled (old behavior)
    // When pagination is enabled, the CostCentersPage uses reloadKey to trigger data refetch
    if (reloadKey !== 0 && !billingCostCentersUIChanges) {
      // eslint-disable-next-line no-self-assign
      window.location.href = window.location.href
    }
  }, [reloadKey, billingCostCentersUIChanges])

  const shouldShowServerSidePagination =
    hasNextPage || currentPage > 1 || (totalCount !== undefined && totalCount > pageSize)

  const shouldShowClientSidePagination = currData.length > pageSize

  return (
    <>
      <Box sx={{...boxStyle, p: 0, overflow: 'hidden'}}>
        <Box
          as="table"
          sx={
            billingAddCostCenterDescription
              ? {
                  ...tableContainerStyle,
                  width: '100%',
                  tableLayout: 'fixed',
                }
              : tableContainerStyle
          }
          data-hpc
        >
          <Box as="thead" sx={{...tableHeaderStyle, alignItems: 'center', display: 'flex'}}>
            <Box as="tr" sx={{flex: 1}}>
              <Box as="td" sx={{mt: '6px', mb: '6px'}}>
                {billingCostCentersUIChanges ? totalCount : costCenters.length} {selectedTab}{' '}
                {Pluralize('cost center', billingCostCentersUIChanges ? totalCount : costCenters.length)}
              </Box>
            </Box>
          </Box>
          <tbody>
            {pagedData.map(costCenter => {
              const resourceByOrg = costCenter.resources.filter(resource => resource.type === ResourceType.Org)
              const resourceByRepo = costCenter.resources.filter(resource => resource.type === ResourceType.Repo)
              const resourceByUser = costCenter.resources.filter(resource => resource.type === ResourceType.User)

              return (
                <Box
                  as="tr"
                  key={costCenter.costCenterKey.uuid}
                  sx={{
                    ...tableRowStyle,
                    ...tableRowStyleRowtoCol,
                  }}
                >
                  <Box
                    as="td"
                    sx={{
                      display: 'flex',
                      flex: '1 1 40%',
                      alignItems: 'center',
                      minWidth: 0,
                      overflow: 'hidden',
                    }}
                  >
                    <Box
                      sx={
                        billingAddCostCenterDescription
                          ? {
                              ...tableDataCellStyleName,
                              flex: 1,
                              minWidth: 0,
                              overflow: 'hidden',
                            }
                          : tableDataCellStyleName
                      }
                    >
                      <div style={{display: 'flex', flexDirection: 'column', minWidth: 0, width: '100%'}}>
                        <div className={styles.nameLabelContainer}>
                          <Text
                            sx={{
                              fontWeight: 'bold',
                              fontSize: 1,
                              wordBreak: 'break-word',
                            }}
                          >
                            {costCenter.name}
                          </Text>
                          {selectedTab === CostCenterTabs.Deleted && (
                            <Label variant="attention" sx={{flexShrink: 0}}>
                              Deleted
                            </Label>
                          )}
                        </div>
                        {billingAddCostCenterDescription && costCenter.description && (
                          <span
                            style={{
                              fontSize: '12px',
                              color: 'GrayText',
                              display: 'block',
                              overflow: 'hidden',
                              textOverflow: 'ellipsis',
                              whiteSpace: 'nowrap',
                              maxWidth: '100%',
                            }}
                          >
                            {costCenter.description}
                          </span>
                        )}
                      </div>

                      {isStafftoolsRoute && (
                        <Text
                          sx={{
                            fontSize: '12px',
                            color: 'fg.muted',
                          }}
                        >
                          {costCenter.costCenterKey.uuid}
                        </Text>
                      )}
                    </Box>

                    <Box
                      sx={
                        billingAddCostCenterDescription
                          ? {
                              py: 2,
                              px: 3,
                              display: ['block', 'none'],
                              flexShrink: 0,
                            }
                          : {
                              py: 2,
                              px: 3,
                              display: ['block', 'none'],
                            }
                      }
                    >
                      <CostCenterActionMenu costCenter={costCenter} />
                    </Box>
                  </Box>
                  {/* The second column displays the number of resources associated with the cost center */}
                  <Box
                    as="td"
                    sx={
                      billingAddCostCenterDescription
                        ? {
                            minWidth: '138px',
                            flex: '0 0 138px',
                          }
                        : {
                            minWidth: '138px',
                          }
                    }
                  >
                    <Text sx={{ml: [3, 2, 2], whiteSpace: 'nowrap'}}>
                      <OrganizationIcon size={16} /> {Pluralize('Organization', resourceByOrg.length, true)}
                    </Text>
                  </Box>
                  <Box
                    as="td"
                    sx={
                      billingAddCostCenterDescription
                        ? {
                            minWidth: '128px',
                            flex: '0 0 128px',
                          }
                        : {
                            minWidth: '128px',
                          }
                    }
                  >
                    <Text sx={{ml: [3, 2, 2], whiteSpace: 'nowrap'}}>
                      <RepoIcon size={16} /> {Pluralize('Repository', resourceByRepo.length, true)}
                    </Text>
                  </Box>
                  <Box
                    as="td"
                    sx={
                      billingAddCostCenterDescription
                        ? {
                            minWidth: '104px',
                            pb: [3, 0, 0],
                            flex: '0 0 104px',
                          }
                        : {
                            minWidth: '104px',
                            pb: [3, 0, 0],
                          }
                    }
                  >
                    <Text sx={{ml: [3, 2, 2], whiteSpace: 'nowrap'}}>
                      <PersonIcon size={16} /> {Pluralize('User', resourceByUser.length, true)}
                    </Text>
                  </Box>
                  <Box
                    as="td"
                    sx={
                      billingAddCostCenterDescription
                        ? {
                            py: 2,
                            px: 3,
                            display: ['none', 'table-cell'],
                            flexShrink: 0,
                          }
                        : {
                            py: 2,
                            px: 3,
                            display: ['none', 'table-cell'],
                          }
                    }
                  >
                    <CostCenterActionMenu costCenter={costCenter} />
                  </Box>
                </Box>
              )
            })}
          </tbody>
        </Box>
      </Box>
      {billingCostCentersUIChanges
        ? shouldShowServerSidePagination && (
            <ServerSidePagination
              currentPage={currentPage}
              onPageChange={onServerSidePageChange}
              hasNextPage={hasNextPage}
              hasPreviousPage={hasPreviousPage}
              totalCount={totalCount}
              pageSize={pageSize}
            />
          )
        : shouldShowClientSidePagination && (
            <Pagination pageCount={pageNumber} currentPage={oldCurrentPage} onPageChange={onPageChange} />
          )}
    </>
  )
}
