import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'

import styles from './CostCentersLoadingTable.module.css'

const SKELETON_ROW_COUNT = 5

type Props = {
  showDescription?: boolean
}

function SkeletonRow({showDescription = false}: {showDescription?: boolean}) {
  return (
    <tr className={styles.SkeletonRow}>
      {/* Name cell */}
      <td className={styles.SkeletonNameCell}>
        <div className={styles.SkeletonNameContent}>
          <div className={styles.SkeletonNameWithLabel}>
            <LoadingSkeleton width="140px" height="16px" />
            <LoadingSkeleton width="60px" height="20px" variant="rounded" />
          </div>
          {showDescription && (
            <div className={styles.SkeletonDescription}>
              <LoadingSkeleton width="200px" height="12px" />
            </div>
          )}
        </div>
        {/* Mobile action menu */}
        <div className={styles.SkeletonMobileActionCell}>
          <LoadingSkeleton width="32px" height="32px" variant="rounded" />
        </div>
      </td>
      {/* Organizations cell */}
      <td className={styles.SkeletonOrgCell}>
        <LoadingSkeleton width="16px" height="16px" variant="rounded" />
        <LoadingSkeleton width="100px" height="14px" />
      </td>
      {/* Repositories cell */}
      <td className={styles.SkeletonRepoCell}>
        <LoadingSkeleton width="16px" height="16px" variant="rounded" />
        <LoadingSkeleton width="90px" height="14px" />
      </td>
      {/* Users cell */}
      <td className={styles.SkeletonUserCell}>
        <LoadingSkeleton width="16px" height="16px" variant="rounded" />
        <LoadingSkeleton width="60px" height="14px" />
      </td>
      {/* Desktop action menu */}
      <td className={styles.SkeletonActionCell}>
        <LoadingSkeleton width="32px" height="32px" variant="rounded" />
      </td>
    </tr>
  )
}

export default function CostCentersLoadingTable({showDescription = false}: Props) {
  return (
    <div className={styles.TableContainer}>
      <table className={styles.Table} data-hpc aria-label="Loading cost centers">
        <thead className={styles.TableHeader}>
          <tr className={styles.TableRow}>
            <td className={styles.HeaderCell}>
              <span className={styles.TableHeaderText}>
                <LoadingSkeleton width="200px" height="14px" />
              </span>
            </td>
          </tr>
        </thead>
        <tbody>
          {Array.from({length: SKELETON_ROW_COUNT}).map((_, index) => (
            // eslint-disable-next-line @eslint-react/no-array-index-key
            <SkeletonRow key={index} showDescription={showDescription} />
          ))}
        </tbody>
      </table>
    </div>
  )
}
