import {useEffect, useRef} from 'react'
import type {JSONRequestInit} from '@github-ui/verified-fetch'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import useRoute from './use-route'
import {USAGE_ROUTE, REPO_USAGE_ROUTE, NET_USAGE_ROUTE, USAGE_CHART_DATA_ROUTE, USAGE_TABLE_DATA_ROUTE} from '../routes'

export const HTTPMethod = {
  DELETE: 'DELETE',
  GET: 'GET',
  PATCH: 'PATCH',
  POST: 'POST',
  PUT: 'PUT',
} as const

export type HTTPMethod = (typeof HTTPMethod)[keyof typeof HTTPMethod]

export type UseRequestResponse = {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  data: any
  ok: boolean
  statusCode: number
}

export async function doRequest<IBody>(
  method: HTTPMethod,
  path: string,
  body?: IBody,
  signal?: AbortSignal,
): Promise<UseRequestResponse> {
  const opts: JSONRequestInit = {method, body, signal}
  const response = await verifiedFetchJSON(path, opts)
  const data = await response.json()
  return {data, ok: response.ok, statusCode: response.status}
}

interface UseRequestProps<Path extends string, FullPath extends string> {
  route: Route<Path, FullPath>
  // Additional URL params to use when generating the path
  args?: {[K in keyof ExtractRouteParams<FullPath>]: string | number}
  // Additional query params to append to the generated path
  reqParams?: Record<string, string>
  noop?: boolean
  // Optional JSON body for POST and PUT requests
  // Optional callback run before making a request
  onStart?: () => void
  // Optional callback run after making the request and receiving an ok status code
  onSuccess?: (response: UseRequestResponse) => void
  // Optional callback run after making the request and receiving an error status code OR an exception is thrown
  onError?: (response: UseRequestResponse | string) => void
  // Optional HTTP method to use for the request
  method?: HTTPMethod
  // Optional client-side key to trigger a refetch when changed (not sent to server)
  requestKey?: number
}

// This hook allows you to make JSON requests to Billing vNext routes and handle responses via the provided callbacks.
// The hook wraps a useEffect, so a request will be fired any time the dependency array changes.
export default function useRequest({
  route,
  reqParams,
  noop = false,
  onStart = () => {},
  onSuccess = () => {},
  onError = () => {},
  method = HTTPMethod.GET,
  requestKey,
}: UseRequestProps<string, string>) {
  const onStartRef = useRef(onStart)
  const onSuccessRef = useRef(onSuccess)
  const onErrorRef = useRef(onError)

  // Keep refs up to date to avoid re-running the effect when callbacks change
  useEffect(() => {
    onStartRef.current = onStart
    onSuccessRef.current = onSuccess
    onErrorRef.current = onError
  })

  // Remove customer_id from reqParams if this is not a cost center request, because the default customer_id
  // should always be the current entity. This will avoid requesting data for the wrong entity.
  // TODO: cost center query params should be extracted to cost_center_id instead.
  const routes = [USAGE_ROUTE, NET_USAGE_ROUTE, REPO_USAGE_ROUTE, USAGE_CHART_DATA_ROUTE, USAGE_TABLE_DATA_ROUTE]
  const costCenterRegExp = new RegExp(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/)
  if (routes.includes(route) && !costCenterRegExp.test(reqParams?.customer_id || '')) {
    delete reqParams?.customer_id
  }

  const {path} = useRoute(route, {}, reqParams)

  if (path === undefined) onError('Invalid route')

  useEffect(() => {
    if (noop) return

    const abortController = new AbortController()

    const getData = async () => {
      try {
        const response = await doRequest(method, path, undefined, abortController.signal)

        // Check if the request was aborted before processing the response
        if (abortController.signal.aborted) {
          return
        }

        if (response.ok) {
          onSuccessRef.current(response)
        } else {
          onErrorRef.current(response)
        }
      } catch (error) {
        // Don't call onError for aborted requests
        if (error instanceof Error && error.name === 'AbortError') {
          return
        }

        onErrorRef.current('Unknown error occurred')
        throw error
      }
    }

    onStartRef.current()
    getData()

    // Cleanup function to abort the request if the effect is cleaned up
    return () => {
      abortController.abort()
    }
  }, [path, method, noop, requestKey])
}
