import {Box, Heading, Text} from '@primer/styled-react'
import {use, useEffect, useState} from 'react'

import type {Product} from '../../types/products'
import {Fonts} from '../../utils/style'
import type {PricingDetails} from '../../types/pricings'
import styles from './BudgetSelectedProduct.module.css'
import {BudgetCopilotPolicyLink} from './BudgetCopilotPolicyLink'
import {PageContext} from '../../App'

interface Props {
  budgetValue: string
  enabledProducts: Product[]
  enabledSkus: PricingDetails[]
}

export function BudgetSelectedProduct({budgetValue, enabledProducts, enabledSkus}: Props) {
  const [budgetValueName, setBudgetValueName] = useState<string>('')
  const [budgetHeaderName, setBudgetHeaderName] = useState<string>('')
  const {isOrganizationRoute, isUserRoute} = use(PageContext)

  useEffect(() => {
    const product = enabledProducts.find(item => item.name === budgetValue)
    if (product) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setBudgetValueName(product.friendlyProductName)
      setBudgetHeaderName('Product')
      return
    }

    const sku = enabledSkus.find(item => item.sku === budgetValue)
    if (sku) {
      setBudgetValueName(sku.friendlyName)
      setBudgetHeaderName('SKU')
    }

    if (budgetValue === 'premium_requests') {
      setBudgetHeaderName('SKU')
      setBudgetValueName('All Premium Request SKUs')
    }
  }, [budgetValue, enabledProducts, enabledSkus])

  return (
    <Box sx={{mb: 4}}>
      <Heading as="h2" sx={{fontSize: Fonts.SectionHeadingFontSize, mb: 2}} className="Box-title">
        {budgetHeaderName ?? 'Unknown'}
      </Heading>
      <div className="Box">
        <div className="Box-row">
          <Text sx={{fontWeight: 'bold'}}>{budgetValueName ?? 'Unknown'}</Text>
          {budgetValue === 'premium_requests' && (
            <>
              <p className={styles.BundleBudgetText}>
                A budget for all SKUs that consume premium requests
                {!isUserRoute ? (
                  <>
                    , where <BudgetCopilotPolicyLink isOrganizationRoute={isOrganizationRoute} />
                  </>
                ) : (
                  '.'
                )}
              </p>
              <span className={styles.BundleBudgetSubtext}>Supported SKUs:</span>
              <ul className={styles.BundleBudgetList}>
                <li>Copilot premium requests</li>
                <li>Coding Agent premium requests</li>
                <li>Spark premium requests</li>
              </ul>
            </>
          )}
        </div>
      </div>
    </Box>
  )
}
