import {use} from 'react'
import styles from './PremiumRequestsUsageTable.module.css'
import {Text, Heading, Pagination} from '@primer/react'
import {InfoIcon} from '@primer/octicons-react'

import {PageContext} from '../../../App'
import {RequestState, UsageGrouping, UsagePeriod} from '../../../enums'
import {useCopilotUsageTableData} from '../../../hooks/usage'

import {ErrorComponent, NoDataComponent} from '../..'
import PremiumRequestUsageTableRow from './PremiumRequestUsageTableRow'
import {getPeriodText} from '../../../utils'

import type {Filters} from '../../../types/usage'
import UsageTableRowSkeleton from '../UsageTable/UsageTableRowSkeleton'
import utilities from '../../utilities.module.css'

interface Props {
  filters: Filters
  setFilters?: (filters: Filters) => void
}

const loadingStates = new Set<RequestState>([RequestState.INIT, RequestState.LOADING])

export default function PremiumRequestsUsageTable({filters, setFilters}: Props) {
  const {isUserRoute} = use(PageContext)

  const currentPage = filters.page ?? 1

  const {usageTableResponse, requestState: requestState} = useCopilotUsageTableData({filters, currentPage})
  const usageTableData = usageTableResponse?.table
  const pageCount = usageTableResponse?.numPages || 1
  const totalResources = usageTableResponse?.totalResources || 0

  const onPageChange = (e: React.MouseEvent, page: number) => {
    e.preventDefault()
    setFilters?.({...filters, page})
  }

  const showProgressBar =
    filters.group?.type === UsageGrouping.USER &&
    (filters.period?.type === UsagePeriod['THIS_MONTH'] || filters.period?.type === UsagePeriod['LAST_MONTH'])

  const showFooter = () =>
    requestState === RequestState.IDLE &&
    (filters.group?.type === UsageGrouping.USER ||
      filters.group?.type === UsageGrouping.ORG ||
      filters.group?.type === UsageGrouping.COSTCENTER) &&
    pageCount >= 10

  const footerCopy = () => {
    let groupText = ''
    if (filters.group?.type === UsageGrouping.USER) {
      groupText = 'users'
    } else if (filters.group?.type === UsageGrouping.ORG) {
      groupText = 'organizations'
    } else if (filters.group?.type === UsageGrouping.COSTCENTER) {
      groupText = 'cost centers'
    }

    return (
      <>
        <InfoIcon size={16} /> The table above displays usage for the top 100 {groupText}. To view usage for all{' '}
        {groupText}, download the premium requests usage report.
      </>
    )
  }

  if (requestState === RequestState.ERROR) {
    return (
      <ErrorComponent className={utilities.AspectRatio3to1} testid="usage-loading-error" text="Something went wrong" />
    )
  }

  if (requestState === RequestState.IDLE && usageTableData?.rows.length === 0) {
    // personal accounts do not show the usage chart which displays a fall back empty usage tile in the case of no usage
    // with this, instead of hiding the usage table, we want to show the fall back empty usage tile here.
    if (isUserRoute) {
      return <NoDataComponent className={utilities.AspectRatio3to1} testid="no-usage-data-card" text="No usage found" />
    } else {
      return null
    }
  }

  const getPaginationText = (itemsPerPage = 10): string => {
    const startItem = (currentPage - 1) * itemsPerPage + 1
    const endItem = Math.min(currentPage * itemsPerPage, totalResources)
    if (startItem === endItem) {
      return `${startItem} of ${totalResources}`
    }
    return `${startItem}-${endItem} of ${totalResources}`
  }

  return (
    <div>
      <div className={styles.usageTableHeaderContainer}>
        <Heading as="h3" variant="small">
          Usage breakdown
        </Heading>
        <Text size="small" className={styles.hintText}>
          {`Usage for ${getPeriodText(filters.period)}. Price per premium request is $0.04.`}
        </Text>
      </div>
      <div className={styles.usageTableBodyContainer}>
        <div className={styles.usageTableBodyTable} data-testid="usage-table">
          <div className={styles.usageTableBodyThead}>
            <div className={styles.usageTableBodyTr}>
              {usageTableData?.columns.map((column, index) => (
                <div
                  key={`column-header-${column.name}`}
                  className={index === 0 ? styles.usageTableBodyIdentifierCell : styles.usageTableBodyFixedWidthCell}
                >
                  {column.name}
                </div>
              ))}
            </div>
          </div>
          <div data-testid="usage-table-rows">
            {loadingStates.has(requestState) && (
              <span data-testid="usage-table-row-skeletons">
                <UsageTableRowSkeleton showQuantity={false} showPricePerUnit={false} />
                <UsageTableRowSkeleton showQuantity={false} showPricePerUnit={false} />
                <UsageTableRowSkeleton showQuantity={false} showPricePerUnit={false} />
              </span>
            )}
            {requestState === RequestState.IDLE &&
              usageTableData?.rows.map(row => (
                <PremiumRequestUsageTableRow
                  key={row.id}
                  cells={row.cells}
                  groupBy={filters.group}
                  subtable={row.subtable}
                  isSubtable={false}
                  showProgressBar={showProgressBar}
                  premiumRequestsQuota={row.premiumRequestsQuota}
                />
              ))}
          </div>
        </div>
        {pageCount > 1 && (
          <div className={styles.usageTablePagination}>
            {totalResources !== undefined && (
              <Text size="small" className={styles.usageTablePaginationText}>
                {getPaginationText()}
              </Text>
            )}
            <Pagination
              pageCount={pageCount}
              currentPage={currentPage}
              onPageChange={onPageChange}
              surroundingPageCount={3}
            />
          </div>
        )}
      </div>
      {showFooter() && <div className={styles.usageTableFooter}>{footerCopy()}</div>}
    </div>
  )
}
