import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useSearchParams} from '@github-ui/use-navigate'

import {ErrorComponent} from '../components'
import BudgetForm from '../components/budget/BudgetForm'
import Layout from '../components/Layout'

import type {AdminRole, Customer} from '../types/common'
import type {Product} from '../types/products'
import type {PricingDetails} from '../types/pricings'
import styles from './BudgetNewPage.module.css'

export interface BudgetNewPagePayload {
  slug: string
  current_user_id: string
  adminRoles: AdminRole[]
  enabledProducts: Product[]
  enabledSkus: PricingDetails[]
  show_missing_payment_banner: boolean
  show_models_banner: boolean
  showCopilotPremiumBanner: boolean
  copilotPremiumPolicyLink: string
  customer: Customer
  isCopilotStandalone: boolean
}

export function BudgetNewPage() {
  const payload = useRoutePayload<BudgetNewPagePayload>()
  const {
    enabledProducts,
    enabledSkus,
    slug,
    current_user_id,
    adminRoles,
    show_missing_payment_banner: showMissingPaymentBanner,
    show_models_banner: showModelsBanner,
    customer,
  } = payload

  const [searchParams] = useSearchParams()
  const initialProduct = searchParams.get('product') ?? undefined
  const initialScope = searchParams.get('scope') ?? undefined
  const initialUserId = searchParams.get('user') ?? undefined
  const initialAmountStr = searchParams.get('amount')
  const initialAmount = (() => {
    if (initialAmountStr === null) return undefined
    const parsed = Number(initialAmountStr)
    return Number.isFinite(parsed) && parsed >= 0 ? parsed : undefined
  })()

  return (
    <Layout>
      {enabledProducts.length > 0 ? (
        <BudgetForm
          slug={slug}
          currentUserId={current_user_id}
          adminRoles={adminRoles}
          enabledProducts={enabledProducts}
          enabledSkus={enabledSkus}
          showMissingPaymentBanner={showMissingPaymentBanner}
          showCopilotPremiumBanner={payload.showCopilotPremiumBanner}
          copilotPremiumPolicyLink={payload.copilotPremiumPolicyLink}
          showModelsBanner={showModelsBanner}
          customer={customer}
          isCopilotStandalone={payload.isCopilotStandalone}
          initialProduct={initialProduct}
          initialScope={initialScope}
          initialUserId={initialUserId}
          initialAmount={initialAmount}
        />
      ) : (
        <ErrorComponent
          className={styles.errorComponentNoBorder}
          testid="new-budget-form-loading-error"
          text="Something went wrong"
        />
      )}
    </Layout>
  )
}
